class ValidationError(RuntimeError):
    pass


CURRENT_MUTATION_LOCK_FORMAT = "agent-assure-s1-successor-mutation-lock/3"


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValidationError(message)


def validate_execution_root_name(name: str, label: str) -> str:
    """Validate the compact, full-entropy execution nonce without path aliases."""
    require(
        isinstance(name, str) and re.fullmatch(r"s3-[0-9a-f]{32}", name) is not None,
        f"{label} execution-root name is not canonical",
    )
    token = name[3:]
    parsed = uuid.UUID(hex=token)
    require(
        parsed.version == 4 and parsed.variant == uuid.RFC_4122 and parsed.hex == token,
        f"{label} execution-root nonce is not canonical RFC 4122 version 4",
    )
    return name


def register_execution_root(name: str, seen: set[str], label: str) -> None:
    validate_execution_root_name(name, label)
    require(name not in seen, f"execution root was reused across receipt nodes: {label}")
    seen.add(name)


def native_windows_launch_budget(argv: list[str]) -> dict[str, int]:
    """Bound the actual CreateProcess application and serialized argv in UTF-16."""
    require(
        isinstance(argv, list)
        and bool(argv)
        and all(isinstance(value, str) and bool(value) and "\0" not in value for value in argv),
        "native Windows command argv is invalid",
    )
    executable_units = len(argv[0].encode("utf-16-le", "strict")) // 2
    command_line_units = len(subprocess.list2cmdline(argv).encode("utf-16-le", "strict")) // 2
    require(executable_units <= 259, "native Windows executable path exceeds 259 UTF-16 code units")
    require(
        command_line_units <= 32766,
        "native Windows command line exceeds 32766 UTF-16 code units excluding NUL",
    )
    return {
        "executable_path_utf16_units": executable_units,
        "command_line_utf16_units": command_line_units,
    }


def python311_fixture_path_budget(execution_root: str) -> list[dict[str, int]]:
    """Check the two known recursive fixture executables before creating a root."""
    root = PureWindowsPath(execution_root)
    require(
        str(root) == execution_root and str(root.parent) == r"C:\tmp",
        "Python 3.11 fixture budget root is outside canonical C:\\tmp",
    )
    validate_execution_root_name(root.name, "Python 3.11 fixture path budget")
    reports = []
    for fixture, suffix in (
        ("test_post_r2_descendant_runtim0", "recursive-policy"),
        ("test_post_r2_descendant_guard_0", "guard-recursion"),
    ):
        executable = (
            root
            / "command-05"
            / "temp"
            / "p"
            / fixture
            / "external-process-temp-root"
            / ("agent-assure-s1-post-r2-process-temp-" + suffix)
            / "descendant-runtime"
            / "Scripts"
            / "python.exe"
        )
        report = native_windows_launch_budget([str(executable), "-I", "-S", "-B"])
        require(
            report["executable_path_utf16_units"] <= 239,
            "known Python 3.11 recursive fixture exceeds its conservative 239-unit path budget",
        )
        reports.append(report)
    return reports


def native_launch_path_policy_self_test() -> tuple[int, int]:
    """Exercise native boundaries and compact root provenance without child processes."""
    launch_vectors = 0
    short = r"C:\p.exe"
    boundary = "C:\\" + "x" * 252 + ".exe"
    unicode_boundary = "C:\\" + "x" * 250 + chr(0x1F600) + ".exe"
    argument = "x" * (32766 - len(short) - 1)
    for argv in (
        [boundary],
        [short, argument],
        [unicode_boundary],
        [r"C:\Program Files\python.exe", "a b", 'x"y', "trailing \\"],
    ):
        report = native_windows_launch_budget(argv)
        require(
            report
            == {
                "executable_path_utf16_units": len(argv[0].encode("utf-16-le")) // 2,
                "command_line_utf16_units": len(subprocess.list2cmdline(argv).encode("utf-16-le"))
                // 2,
            },
            "native launch boundary projection self-test failed",
        )
        launch_vectors += 1
    for argv in (
        [boundary + "x"],
        [short, argument + "x"],
        [unicode_boundary + chr(0x1F600)],
        [short, "embedded\0nul"],
        [],
    ):
        rejected = False
        try:
            native_windows_launch_budget(argv)
        except ValidationError:
            rejected = True
        require(rejected, "native launch over-budget or malformed vector was accepted")
        launch_vectors += 1
    fixture_reports = python311_fixture_path_budget(r"C:\tmp\s3-00000000000040008000000000000000")
    require(
        [item["executable_path_utf16_units"] for item in fixture_reports] == [211, 210],
        "known recursive Python 3.11 fixture geometry changed",
    )
    launch_vectors += len(fixture_reports)
    root_vectors = 0
    first = "s3-00000000000040008000000000000001"
    second = "s3-00000000000040008000000000000002"
    seen: set[str] = set()
    register_execution_root(first, seen, "first receipt")
    register_execution_root(second, seen, "second receipt")
    root_vectors += 2
    for name in (
        first,
        "s3-00000000000030008000000000000001",
        "s3-00000000000040007000000000000001",
        first.upper(),
        first + "0",
        first.replace("s3-", "../s3-"),
        "agent-assure-s1-v3-node-execution-"
        + PACKAGE_ID
        + "-01-00000000-0000-4000-8000-000000000001",
    ):
        rejected = False
        try:
            register_execution_root(name, seen, "negative root vector")
        except ValidationError:
            rejected = True
        require(rejected, "invalid or reused compact execution-root vector was accepted")
        root_vectors += 1
    require(seen == {first, second}, "rejected roots changed the receipt root registry")
    return launch_vectors, root_vectors


def parse_filetime_decimal(value: Any, label: str) -> int:
    """Parse one canonical positive UInt64 FILETIME decimal string."""

    require(
        isinstance(value, str) and re.fullmatch(r"[1-9][0-9]{0,19}", value) is not None,
        f"{label} is not a canonical positive decimal string",
    )
    parsed = int(value)
    require(
        parsed <= (2**64) - 1 and str(parsed) == value,
        f"{label} is outside canonical UInt64 FILETIME range",
    )
    return parsed


def validate_python311_project_install_argv(argv: Iterable[str]) -> None:
    """Require the exact corrected, wheel-only uv project-install recipe."""

    observed = tuple(argv)
    require(
        observed == PYTHON311_PROJECT_INSTALL_ARGV,
        "Python 3.11 project-install argv differs from the exact corrected recipe",
    )
    require(
        observed.count("--only-binary") == 1
        and observed[observed.index("--only-binary") + 1] == ":all:"
        and "--no-build" not in observed,
        "Python 3.11 project-install argv does not preserve the nonconflicting wheel-only policy",
    )


def reject_duplicate_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValidationError(f"duplicate JSON key: {key!r}")
        result[key] = value
    return result


def reject_nonfinite_number(value: str) -> Any:
    raise ValidationError(f"non-finite JSON number rejected: {value}")


def validate_decoded_json_value(value: Any, *, path: str = "$") -> None:
    """Enforce the exact decoded-value restrictions used by the B3 runner."""

    if isinstance(value, bool) or value is None:
        return
    if isinstance(value, int):
        require(
            -(2**53) + 1 <= value <= (2**53) - 1,
            f"integer outside RFC 8785 safe range at {path}",
        )
        return
    if isinstance(value, float):
        require(math.isfinite(value), f"non-finite number at {path}")
        return
    if isinstance(value, str):
        require(unicodedata.normalize("NFC", value) == value, f"non-NFC string at {path}")
        require(
            not any(
                ord(character) < 0x20 or 0xD800 <= ord(character) <= 0xDFFF for character in value
            ),
            f"control or surrogate character at {path}",
        )
        return
    if isinstance(value, list):
        for index, item in enumerate(value):
            validate_decoded_json_value(item, path=f"{path}/{index}")
        return
    if isinstance(value, dict):
        for key, item in value.items():
            require(isinstance(key, str), f"non-string object key at {path}")
            validate_decoded_json_value(key, path=f"{path}/<key>")
            validate_decoded_json_value(item, path=f"{path}/{key}")
        return
    raise ValidationError(f"unsupported JSON value {type(value).__name__} at {path}")


def assert_no_reparse_chain(path: Path, owner: str, *, require_exists: bool = True) -> None:
    absolute = path.absolute()
    chain: list[Path] = []
    cursor = absolute
    while True:
        chain.append(cursor)
        if cursor == cursor.parent:
            break
        cursor = cursor.parent
    for component in reversed(chain):
        if not component.exists() and not component.is_symlink():
            if require_exists:
                raise ValidationError(f"{owner} path component is missing: {component}")
            continue
        metadata = component.lstat()
        require(
            not component.is_symlink()
            and not bool(
                getattr(metadata, "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT
            ),
            f"{owner} contains a symlink or reparse point: {component}",
        )


def read_bytes(path: Path) -> bytes:
    return read_bounded_regular_file(path, MAX_JSON_FILE_BYTES, "input")


def read_bounded_regular_file(path: Path, maximum_bytes: int, label: str) -> bytes:
    require(0 <= maximum_bytes <= MAX_JSON_FILE_BYTES, f"invalid byte bound for {label}")
    assert_no_reparse_chain(path, label)
    before = path.lstat()
    require(path.is_file() and not path.is_symlink(), f"missing regular file: {label}: {path}")
    require(
        before.st_size <= maximum_bytes, f"{label} exceeds its {maximum_bytes}-byte bound: {path}"
    )
    with path.open("rb") as handle:
        raw = handle.read(maximum_bytes + 1)
    require(len(raw) <= maximum_bytes, f"{label} grew beyond its byte bound while read: {path}")
    after = path.lstat()
    require(
        (before.st_mode, before.st_ino, before.st_size, before.st_mtime_ns)
        == (after.st_mode, after.st_ino, after.st_size, after.st_mtime_ns)
        and len(raw) == before.st_size,
        f"{label} changed while read: {path}",
    )
    return raw


def sha256_file_exact_size(path: Path, expected_size: int, label: str) -> bytes:
    """Hash exactly the snapshotted byte count and reject a trailing growth byte."""

    require(expected_size >= 0, f"negative exact-hash bound for {label}")
    digest = hashlib.sha256()
    remaining = expected_size
    with path.open("rb") as handle:
        while remaining:
            chunk = handle.read(min(1024 * 1024, remaining))
            require(bool(chunk), f"{label} was truncated while hashed: {path}")
            digest.update(chunk)
            remaining -= len(chunk)
        require(handle.read(1) == b"", f"{label} grew beyond its exact hash bound: {path}")
    return digest.digest()


def require_unchanged_file(path: Path, expected: bytes, label: str) -> None:
    require(
        len(expected) <= MAX_JSON_FILE_BYTES,
        f"expected bytes exceed the protocol bound for {label}",
    )
    require(read_bounded_regular_file(path, len(expected), label) == expected, f"{label} changed")


def load_json(path: Path) -> tuple[Any, bytes]:
    raw = read_bounded_regular_file(path, MAX_JSON_FILE_BYTES, "JSON input")
    require(not raw.startswith(b"\xef\xbb\xbf"), f"UTF-8 BOM rejected: {path}")
    require(b"\r" not in raw, f"carriage return rejected: {path}")
    require(raw.endswith(b"\n"), f"final LF required: {path}")
    return parse_json_bytes(raw, str(path)), raw


def parse_json_bytes(raw: bytes, label: str, *, require_final_lf: bool = True) -> Any:
    require(
        len(raw) <= MAX_JSON_FILE_BYTES, f"JSON input exceeds {MAX_JSON_FILE_BYTES} bytes: {label}"
    )
    require(not raw.startswith(b"\xef\xbb\xbf"), f"UTF-8 BOM rejected: {label}")
    require(b"\r" not in raw, f"carriage return rejected: {label}")
    if require_final_lf:
        require(raw.endswith(b"\n"), f"final LF required: {label}")
    try:
        text = raw.decode("utf-8", "strict")
    except UnicodeDecodeError as exc:
        raise ValidationError(f"invalid UTF-8: {label}") from exc
    try:
        value = json.loads(
            text,
            object_pairs_hook=reject_duplicate_keys,
            parse_constant=reject_nonfinite_number,
        )
    except (json.JSONDecodeError, ValueError) as exc:
        raise ValidationError(f"invalid strict JSON: {label}: {exc}") from exc
    validate_decoded_json_value(value)
    return value


def canonical(value: Any) -> bytes:
    validate_decoded_json_value(value)
    try:
        return rfc8785.dumps(value)
    except Exception as exc:
        raise ValidationError(f"RFC 8785 canonicalization failed: {exc}") from exc


def domain_digest(domain: str, value: Any) -> str:
    return "sha256:" + hashlib.sha256(domain.encode("ascii") + b"\0" + canonical(value)).hexdigest()


def sha256(raw: bytes) -> str:
    return "sha256:" + hashlib.sha256(raw).hexdigest()


def decode_forensic_base64(value: Mapping[str, Any], label: str) -> bytes:
    """Decode a bounded, canonical base64 forensic envelope and bind its digest."""

    byte_count = value.get("bytes")
    content = value.get("raw_base64")
    require(
        isinstance(byte_count, int)
        and not isinstance(byte_count, bool)
        and 0 <= byte_count <= MAX_EMBEDDED_BLOB_BYTES,
        f"forensic byte count is outside the protocol bound in {label}",
    )
    require(
        isinstance(content, str)
        and len(content) <= MAX_EMBEDDED_BLOB_BASE64_CHARS
        and len(content) == ((byte_count + 2) // 3) * 4,
        f"forensic base64 length does not match byte count in {label}",
    )
    try:
        raw = base64.b64decode(content, validate=True)
    except (ValueError, TypeError) as exc:
        raise ValidationError(f"invalid base64 in {label}") from exc
    require(
        base64.b64encode(raw).decode("ascii") == content,
        f"noncanonical base64 in {label}",
    )
    require(len(raw) == byte_count, f"forensic byte count mismatch in {label}")
    require(sha256(raw) == value.get("raw_sha256"), f"forensic SHA-256 mismatch in {label}")
    return raw


def validate_forensic_text_envelope(value: Mapping[str, Any], label: str) -> bytes:
    """Validate lossless raw text without placing control characters in JSON strings."""

    require(
        set(value)
        == {
            "bytes",
            "raw_sha256",
            "encoding",
            "raw_base64",
            "line_ending",
            "terminal_line_ending",
            "lines",
        },
        f"forensic text envelope member set mismatch in {label}",
    )
    require(value["encoding"] == "utf-8", f"forensic text encoding mismatch in {label}")
    require(value["line_ending"] in {"LF", "CRLF"}, f"forensic line ending mismatch in {label}")
    require(
        isinstance(value["terminal_line_ending"], bool),
        f"forensic terminal-line-ending flag mismatch in {label}",
    )
    lines = value["lines"]
    require(
        isinstance(lines, list) and all(isinstance(item, str) for item in lines),
        f"forensic text lines mismatch in {label}",
    )
    raw = decode_forensic_base64(value, label)
    try:
        decoded = raw.decode("utf-8", "strict")
    except UnicodeDecodeError as exc:
        raise ValidationError(f"forensic text is not strict UTF-8 in {label}") from exc
    separator = "\r\n" if value["line_ending"] == "CRLF" else "\n"
    expected = separator.join(lines)
    if value["terminal_line_ending"]:
        expected += separator
    require(decoded == expected, f"forensic text projection mismatch in {label}")
    return raw


def validate_failed_python311_supersession(claim: Mapping[str, Any]) -> int:
    """Recompute the retained raw envelopes and bind the terminal floor-gate failure."""
    failed = claim["supersession"]["failed_python311_node_execution_ceremony"]
    require(
        failed == FAILED_PYTHON311_NODE_EXECUTION_CEREMONY,
        "failed Python 3.11 node-execution forensic binding mismatch",
    )
    package = failed["package"]
    authorization = failed["authorization"]
    objects = failed["git_objects"]
    failure = failed["failure"]
    require(
        failed["format"] == "agent-assure-s1-generation-3-python311-node-execution-failure/1"
        and package["package_id"] == FAILED_PYTHON311_PACKAGE_ID != claim["package_id"]
        and authorization["authorization_id"]
        == FAILED_PYTHON311_AUTHORIZATION_ID
        != claim["authorization_id"]
        and package["kickoff_claim"]["claim_nonce"]
        == FAILED_PYTHON311_CLAIM_NONCE
        != claim["claim_nonce"]
        and package["kickoff_claim"]["format"] == "agent-assure-s1-successor-authorization-claim/11"
        and package["kickoff_claim"]["digest_domain"]
        == "agent-assure:s1-successor-kickoff-claim/v11"
        and package["kickoff_claim"]["spec_revision"] == "7.10-draft"
        and authorization["record"]["format"]
        == "agent-assure-s1-successor-kickoff-authorization/12"
        and authorization["record"]["digest_domain"]
        == "agent-assure:s1-successor-kickoff-authorization-record/v12"
        and objects["k3"]["commit"] == FAILED_PYTHON311_K3
        and objects["k3"]["parent"] == B3
        and objects["r3"]["commit"] == FAILED_PYTHON311_R3
        and objects["r3"]["parent"] == FAILED_PYTHON311_K3
        and objects["r3"]["delta_paths"] == R3_EXACT_ALLOWLIST,
        "failed Python 3.11 package, authority, or commit lineage mismatch",
    )
    envelopes = 0

    def walk(value: Any, label: str) -> None:
        nonlocal envelopes
        if isinstance(value, dict):
            if "raw_base64" in value:
                decode_forensic_base64(value, label)
                require(
                    value.get("hard_link_count") == 1,
                    f"failed Python 3.11 forensic source is not single-linked: {label}",
                )
                envelopes += 1
            for name, child in value.items():
                walk(child, f"{label}/{name}")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                walk(child, f"{label}/{index}")

    walk(failed, "failed Python 3.11")
    require(envelopes == 17, "failed Python 3.11 forensic raw-envelope count mismatch")
    receipts = failed["completed_preclosure_receipts"]
    require(
        receipts["count"] == 6
        and receipts["ordinals"] == list(range(1, 7))
        and receipts["semantic_digests_independently_recomputed"]
        and [item["node_id"] for item in receipts["receipts"]] == PRE_IDS[:6]
        and all(item["status"] == "passed" for item in receipts["receipts"]),
        "failed Python 3.11 completed receipt prefix mismatch",
    )
    junit = failure["junit"]
    identities = junit["identity_set"]["identities"]
    identity_tuples = [(item["classname"], item["name"]) for item in identities]
    require(
        (junit["tests"], junit["failures"], junit["errors"], junit["skipped"], junit["passed"])
        == (311, 9, 0, 0, 302)
        and len(identities) == len(set(identity_tuples)) == 311
        and identity_tuples
        == sorted(
            identity_tuples,
            key=lambda item: (
                item[0].encode("utf-8"),
                item[1].encode("utf-8"),
            ),
        )
        and domain_digest(PYTHON311_TEST_IDENTITY_DOMAIN, identities)
        == PYTHON311_TEST_IDENTITY_DIGEST
        and junit["identity_set"]["semantic_digest"] == PYTHON311_TEST_IDENTITY_DIGEST
        and junit["identity_set"]["matches_signed_identity_set"]
        and junit["source"]["bytes"] == 140259
        and junit["source"]["raw_sha256"]
        == "sha256:3c5e26cd723ffa70d9e13ee4833f0355f213939afda24fa9dc6d57407e2e78a7"
        and len(junit["nine_failures"]) == 9,
        "failed Python 3.11 JUnit outcome or exact test identities mismatch",
    )
    command5 = failure["execution_root"]["command_captures"][4]
    require(
        failure["node_ordinal"] == 7
        and failure["command_ordinal"] == 5
        and failure["node_id"] == PRE_IDS[6]
        and command5["command_ordinal"] == 5
        and command5["exit_code"] == 1
        and command5["stdout"]["bytes"] == 87720
        and command5["stdout"]["raw_sha256"]
        == "sha256:44ec1a0ef12fcfc5d511bb3c63378a2469a566ffc2b37ab171cbf269868d8f7c"
        and command5["stderr"]["bytes"] == 0
        and failure["execution_root"]["command6"] == "not_reached"
        and failure["execution_root"]["canonical_receipt7"] == "absent",
        "failed Python 3.11 command capture or receipt boundary mismatch",
    )
    lock = failure["transaction_lock"]
    lock_value = parse_json_bytes(
        decode_forensic_base64(lock, "failed Python 3.11 lock"), "failed Python 3.11 lock"
    )
    require(
        lock_value["format"] == "agent-assure-s1-successor-mutation-lock/3"
        and lock_value["operation"] == "execute_node"
        and lock_value["process_id"] == 20080
        and lock_value["process_started_filetime_100ns"] == "134377166237268557"
        and lock["owner_liveness_observation"]["status"] == "not_running_unattested"
        and lock["owner_liveness_observation"]["winerror"] == 87
        and lock["preserve_unchanged"],
        "failed Python 3.11 retained lock binding mismatch",
    )
    replacement = claim["supersession"]["replacement"]
    disposition = failed["disposition"]
    require(
        disposition["generation_2_remains_current"]
        and disposition["r3_acceptance_effect"] == "none"
        and all(
            not disposition[name]
            for name in (
                "resume_retry_or_reuse_authorized",
                "recover_execute_node_authorized",
                "prior_receipt_reuse_authorized",
                "k3_reuse_authorized",
                "r3_reuse_authorized",
                "runtime_state_reuse_authorized",
                "manual_unlock_authorized",
                "lock_deletion_authorized",
                "manual_bypass_authorized",
                "evidence_deletion_authorized",
            )
        )
        and not failed["repair_evidence_requirement"]["manual_bypass_authorized"]
        and all(
            value
            for name, value in failed["repair_evidence_requirement"].items()
            if name != "manual_bypass_authorized"
        )
        and FAILED_PYTHON311_K3 in replacement["forbidden_k3_parents"]
        and FAILED_PYTHON311_R3 in replacement["forbidden_r3_commits"]
        and all(
            not replacement["failed_python311_node_execution_" + suffix]
            for suffix in (
                "k3_reuse_authorized",
                "r3_reuse_authorized",
                "runtime_state_reuse_authorized",
                "recovery_authorized",
            )
        )
        and replacement["failed_python311_node_execution_operational_effect"]
        == "none_for_recovery_replacement_or_further_ceremony_steps"
        and replacement[
            "preserve_failed_python311_node_execution_clone_package_signatures_objects_activation_runtime_wheel_uv_root_journals_execution_roots_receipts_and_lock"
        ],
        "failed Python 3.11 terminal disposition is not fail-closed",
    )
    times = [
        dt.datetime.fromisoformat(item["at_utc"].replace("Z", "+00:00"))
        for item in failed["chronological_fields"]
    ]
    require(
        all(value.tzinfo is not None for value in times)
        and all(a < b for a, b in zip(times[:-1], times[1:], strict=True))
        and times[-1]
        < parse_time(claim["validity"]["prepared_at_utc"])
        < parse_time(claim["validity"]["valid_until_utc"])
        and not failed["forensic_observation"]["independent_witness"]
        and not failed["forensic_observation"][
            "governance_commands_tests_retries_signatures_or_unlocks_executed"
        ]
        and not failed["forensic_observation"]["failed_attempt_files_changed"],
        "replacement claim does not postdate the failed Python 3.11 chronology",
    )
    return envelopes


def validate_failed_native_node8_supersession(claim: Mapping[str, Any]) -> int:
    """Bind the terminal native precondition failure without inventing acceptance."""
    failed = claim["supersession"]["failed_native_node8_execution_ceremony"]
    require(
        failed == FAILED_NATIVE_NODE8_EXECUTION_CEREMONY,
        "failed native node8 forensic binding mismatch",
    )
    package, authorization, objects = (
        failed["package"],
        failed["authorization"],
        failed["git_objects"],
    )
    require(
        failed["format"] == "agent-assure-s1-generation-3-native-node8-execution-failure/1"
        and package["package_id"] == FAILED_NATIVE_NODE8_PACKAGE_ID != claim["package_id"]
        and authorization["authorization_id"]
        == FAILED_NATIVE_NODE8_AUTHORIZATION_ID
        != claim["authorization_id"]
        and package["kickoff_claim"]["claim_nonce"]
        == FAILED_NATIVE_NODE8_CLAIM_NONCE
        != claim["claim_nonce"]
        and package["kickoff_claim"]["format"] == "agent-assure-s1-successor-authorization-claim/12"
        and package["kickoff_claim"]["digest_domain"]
        == "agent-assure:s1-successor-kickoff-claim/v12"
        and package["kickoff_claim"]["spec_revision"] == "7.11-draft"
        and authorization["record"]["format"]
        == "agent-assure-s1-successor-kickoff-authorization/13"
        and authorization["record"]["digest_domain"]
        == "agent-assure:s1-successor-kickoff-authorization-record/v13"
        and objects["k3"]["commit"] == FAILED_NATIVE_NODE8_K3
        and objects["k3"]["parent"] == B3
        and objects["r3"]["commit"] == FAILED_NATIVE_NODE8_R3
        and objects["r3"]["parent"] == FAILED_NATIVE_NODE8_K3
        and objects["r3"]["delta_paths"] == R3_EXACT_ALLOWLIST,
        "failed native node8 identity, authority, or commit lineage mismatch",
    )
    envelopes = 0

    def walk(value: Any, label: str) -> None:
        nonlocal envelopes
        if isinstance(value, dict):
            if "raw_base64" in value:
                decode_forensic_base64(value, label)
                if "hard_link_count" in value:
                    require(
                        value["hard_link_count"] == 1,
                        f"failed native source is multiply linked: {label}",
                    )
                envelopes += 1
            for name, child in value.items():
                walk(child, f"{label}/{name}")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                walk(child, f"{label}/{index}")

    walk(failed, "failed native node8")
    require(envelopes == 38, "failed native node8 raw-envelope count mismatch")
    for role in ("k3", "r3"):
        obj = objects[role]
        raw = base64.b64decode(obj["raw_commit_base64"], validate=True)
        require(
            len(raw) == obj["raw_commit_bytes"]
            and sha256(raw) == obj["raw_commit_sha256"]
            and hashlib.sha1(b"commit " + str(len(raw)).encode("ascii") + b"\0" + raw).hexdigest()
            == obj["commit"],
            f"failed native {role} raw commit envelope mismatch",
        )
    receipts = failed["completed_preclosure_receipts"]
    require(
        receipts["count"] == 7
        and receipts["ordinals"] == list(range(1, 8))
        and receipts["semantic_digests_independently_recomputed"]
        and receipts["every_embedded_command_stream_rechecked_against_retained_capture"]
        and [item["node_id"] for item in receipts["receipts"]] == PRE_IDS[:7]
        and all(item["status"] == "passed" for item in receipts["receipts"]),
        "failed native completed receipt prefix mismatch",
    )
    junit = failed["python311_runtime"]["governed_node7_junit"]
    require(
        (
            junit["tests"],
            junit["failures"],
            junit["errors"],
            junit["skipped"],
            junit["case_identity_count"],
        )
        == (311, 0, 0, 0, 311)
        and junit["identity_digest"] == PYTHON311_TEST_IDENTITY_DIGEST
        and junit["matches_signed_identity_set"],
        "failed native retained governed node7 gate mismatch",
    )
    failure = failed["failure"]
    root = failure["execution_root"]
    require(
        failure["node_ordinal"] == 8
        and failure["command_ordinal"] == 1
        and failure["node_id"] == PRE_IDS[7]
        and failure["outer_tool_report"]["node_command_exit_code"] == 2
        and failure["outer_tool_report"]["execute_node_exit_code"] == 1
        and not failure["native_full_pytest_started"]
        and root["stdout"]["bytes"] == 0
        and root["stderr"]["bytes"] == 74
        and root["stderr"]["raw_sha256"]
        == "sha256:dba83fabfa32623cbd64b4c6d46c678d2772c229c10535a749d17a131a4e289c"
        and root["semantic_output"] == root["receipt8"] == "absent"
        and not failure["original_nested_Git_stdout"]["exact_failed_bytes_available"]
        and failure["original_nested_Git_stdout"]["raw_sha256"] is None,
        "failed native command boundary or original nested-output limit mismatch",
    )
    text_fields = (
        "bytes",
        "raw_sha256",
        "raw_base64",
        "encoding",
        "line_ending",
        "terminal_line_ending",
        "lines",
    )
    stderr = validate_forensic_text_envelope(
        {key: root["stderr"][key] for key in text_fields}, "failed native stderr"
    )
    require(
        stderr == b"v1 S1 governance error: private roadmap bytes are present in Git history\r\n",
        "failed native raw stderr differs from the exact retained bytes",
    )
    lock = failure["transaction_lock"]
    lock_value = parse_json_bytes(
        decode_forensic_base64(lock, "failed native lock"), "failed native lock"
    )
    require(
        lock["bytes"] == 304
        and lock["raw_sha256"]
        == "sha256:6276f4b56298f4f476dde9f52bc76f0c876a1aa710b0fea921977b54d6b98704"
        and lock_value["operation"] == "execute_node"
        and lock_value["process_id"] == 27024
        and lock_value["process_started_filetime_100ns"] == "134377966497829357"
        and lock["owner_liveness_observation"]["status"] == "not_running_unattested"
        and lock["owner_liveness_observation"]["winerror"] == 87
        and lock["preserve_unchanged"],
        "failed native retained transaction lock mismatch",
    )
    reproduction = failed["defect"]["primary"]["read_only_reproduction"]
    blocker = failed["defect"]["additional_unreached_native_runtime_blocker"]
    proof = blocker["same_exact_rows_dual_domain_proof"]
    require(
        reproduction["returned_rows"] == 9
        and reproduction["all_returned_types"] == "tag"
        and reproduction["control_rows_identical"]
        and reproduction["ref_surface_identical"]
        and reproduction["roadmap_commit_path_history_query"]["exit_code"] == 0
        and reproduction["roadmap_commit_path_history_query"]["stdout"]["bytes"] == 0
        and not reproduction["original_nested_Git_stdout_available"]
        and blocker["source_tuple"]["sha256"]
        == "sha256:f1cfe929055f4f012e8e98b46087d11ea7b901e23a11232bc891e91010e0e49f"
        and proof["same_exact_stable_rows_for_both_domains"]
        and proof["file_count"] == 5473
        and proof["size_bytes"] == 92718662
        and proof["native_domain"] == "agent-assure:s1-post-r2-test-runtime-inventory/v1"
        and proof["native_sha256"]
        == "sha256:feb0fb7ab319b62f1f085f98c1db3b5ac81071d95e60392fb9b30ba0f343c9d0"
        and proof["successor_sha256"]
        == "sha256:47ff00e0c74d07b7060b25285d886b079dfb62322b60dc657ebd5a39dc69db20"
        and blocker["signed_successor_inventory_still_matches"]
        and not blocker["native_expected_matches_measured"]
        and not blocker["original_node8_reached_this_check"],
        "failed native reproduction or separate unreached dual-domain blocker mismatch",
    )
    disposition = failed["disposition"]
    replacement = claim["supersession"]["replacement"]
    require(
        disposition["generation_2_remains_current"]
        and disposition["r3_acceptance_effect"] == "none"
        and all(not value for name, value in disposition.items() if name.endswith("_authorized"))
        and all(failed["repair_evidence_requirement"].values())
        and FAILED_NATIVE_NODE8_K3 in replacement["forbidden_k3_parents"]
        and FAILED_NATIVE_NODE8_R3 in replacement["forbidden_r3_commits"]
        and all(
            not replacement["failed_native_node8_execution_" + suffix]
            for suffix in (
                "k3_reuse_authorized",
                "r3_reuse_authorized",
                "runtime_state_reuse_authorized",
                "recovery_authorized",
            )
        )
        and replacement["failed_native_node8_execution_operational_effect"]
        == "none_for_recovery_replacement_or_further_ceremony_steps"
        and replacement[
            "preserve_failed_native_node8_execution_clone_package_signatures_objects_activation_runtimes_wheel_uv_roots_journals_receipts_execution_roots_and_lock"
        ],
        "failed native terminal disposition is not fail-closed",
    )
    times = [parse_time(item["at_utc"]) for item in failed["chronological_fields"]]
    require(
        all(a < b for a, b in zip(times[:-1], times[1:], strict=True))
        and times[-1]
        < parse_time(claim["validity"]["prepared_at_utc"])
        < parse_time(claim["validity"]["valid_until_utc"])
        and not failed["forensic_observation"]["independent_witness"]
        and not failed["forensic_observation"][
            "governance_commands_tests_retries_signatures_unlocks_or_network_operations_executed"
        ]
        and not failed["forensic_observation"]["signed_failed_attempt_files_changed"],
        "replacement claim does not prospectively postdate the failed native chronology",
    )
    return envelopes


def parse_r3_runner_protocol_identity(raw: bytes) -> dict[str, str]:
    """Read governed runner constants without importing or executing the runner."""

    symbol_fields = {
        R3_RUNNER_PROTOCOL_IDENTITY["package_id_symbol"]: "package_id",
        R3_RUNNER_PROTOCOL_IDENTITY["check_contracts_format_symbol"]: "check_contracts_format",
        R3_RUNNER_PROTOCOL_IDENTITY["kickoff_claim_format_symbol"]: "kickoff_claim_format",
        R3_RUNNER_PROTOCOL_IDENTITY[
            "kickoff_authorization_format_symbol"
        ]: "kickoff_authorization_format",
    }
    try:
        source = raw.decode("utf-8", "strict")
    except UnicodeDecodeError as exc:
        raise ValidationError("R3 runner is not strict UTF-8") from exc
    try:
        tree = ast.parse(source, filename=R3_RUNNER_PROTOCOL_IDENTITY["path"])
    except SyntaxError as exc:
        raise ValidationError("R3 runner is not valid Python syntax") from exc
    stored = {
        symbol: sum(
            1
            for node in ast.walk(tree)
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store) and node.id == symbol
        )
        for symbol in symbol_fields
    }
    require(
        all(count == 1 for count in stored.values()),
        "R3 runner governed protocol symbol is missing, duplicate, or reassigned",
    )
    values: dict[str, str] = {}
    for node in tree.body:
        if not isinstance(node, ast.AnnAssign) or not isinstance(node.target, ast.Name):
            continue
        field = symbol_fields.get(node.target.id)
        if field is None:
            continue
        require(
            isinstance(node.value, ast.Constant)
            and isinstance(node.value.value, str)
            and node.simple == 1,
            f"R3 runner governed protocol symbol is not one literal assignment: {node.target.id}",
        )
        require(
            field not in values,
            f"R3 runner governed protocol symbol is duplicated: {node.target.id}",
        )
        values[field] = node.value.value
    require(
        set(values) == set(symbol_fields.values()),
        "R3 runner governed protocol identity is incomplete",
    )
    return values


def validate_r3_runner_protocol_identity(
    raw: bytes,
    expected: Mapping[str, Any],
) -> dict[str, str]:
    require(
        dict(expected) == R3_RUNNER_PROTOCOL_IDENTITY,
        "signed R3 runner protocol identity differs from the package contract",
    )
    observed = parse_r3_runner_protocol_identity(raw)
    expected_values = {
        key: expected[key]
        for key in (
            "package_id",
            "check_contracts_format",
            "kickoff_claim_format",
            "kickoff_authorization_format",
        )
    }
    require(observed == expected_values, "R3 runner embedded package/protocol identity mismatch")
    native_expected = {
        "SUCCESSOR_V3_TEST_RUNTIME_IDENTITY": SUCCESSOR_NATIVE_TEST_RUNTIME_IDENTITY,
        "POST_R2_TEST_RUNTIME_INVENTORY_DOMAIN": NATIVE_TEST_RUNTIME_INVENTORY_DOMAIN,
    }
    tree = ast.parse(raw)
    native_stores = {
        name: sum(
            1
            for node in ast.walk(tree)
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store) and node.id == name
        )
        for name in native_expected
    }
    require(
        all(count == 1 for count in native_stores.values()),
        "R3 runner native runtime symbol is missing, duplicate, or reassigned",
    )
    native_values: dict[str, Any] = {}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            require(
                not any(
                    isinstance(target, ast.Name) and target.id in native_expected
                    for target in node.targets
                ),
                "R3 runner native identity requires annotated literal declarations",
            )
        if not isinstance(node, ast.AnnAssign) or not isinstance(node.target, ast.Name):
            continue
        name = node.target.id
        if name not in native_expected:
            continue
        require(
            name not in native_values and node.simple == 1 and node.value is not None,
            "R3 runner native runtime declaration is duplicate or incomplete",
        )
        try:
            value = ast.literal_eval(node.value)
        except (ValueError, TypeError, SyntaxError) as exc:
            raise ValidationError("R3 runner native runtime declaration is not literal") from exc
        if name == "SUCCESSOR_V3_TEST_RUNTIME_IDENTITY":
            require(
                type(value) is tuple
                and len(value) == 3
                and type(value[0]) is int
                and type(value[1]) is int
                and type(value[2]) is str,
                "R3 runner native runtime identity must be an exact (int, int, str) tuple",
            )
        else:
            require(type(value) is bytes, "R3 runner native inventory domain must be literal bytes")
        native_values[name] = value
    require(
        native_values == native_expected,
        "R3 runner native runtime tuple or binary inventory domain is missing or mismatched",
    )
    return observed


R3_TRANSFER_PROBE_PROFILES = frozenset(
    {
        "preparation",
        "kickoff-record-ready",
        "kickoff-imported",
        "successor-branch-initialized",
        "k3-staged",
        "k3-installed",
    }
)
R3_TRACKED_PROBE_PROFILES = frozenset(
    {
        "r3-worktree",
        "r3-staged",
        "r3-installed",
        "c3-staged",
        "c3-installed",
        "a3-installed",
        "post-tag-final",
        "standalone",
    }
)


def prospective_runner_probe_route(profile: str) -> str:
    if profile in R3_TRANSFER_PROBE_PROFILES:
        return "ignored_r3_payload_transfer"
    if profile in R3_TRACKED_PROBE_PROFILES:
        return "tracked_repository"
    raise ValidationError(
        f"no prospective R3 runner compatibility-probe route for profile: {profile}"
    )


def validate_prospective_runner_json_compatibility(
    repository: Path,
    json_documents: Mapping[str, bytes],
    profile: str,
) -> None:
    """Probe every emitted package JSON document with the exact R3 runner."""

    route = prospective_runner_probe_route(profile)
    if route == "ignored_r3_payload_transfer":
        source_root = repository / R3_PAYLOAD_TRANSFER_ROOT
        transfer_files, transfer_directories = exact_entry_surface(source_root)
        require(
            transfer_files == R3_EXACT_ALLOWLIST,
            "R3 payload-transfer file surface differs from the exact allowlist",
        )
        require(
            transfer_directories == parent_directories(R3_EXACT_ALLOWLIST),
            "R3 payload-transfer directory surface differs from the exact allowlist",
        )
    else:
        require(
            route == "tracked_repository",
            "prospective R3 runner probe selected an impossible route",
        )
        source_root = repository
    descriptors = worktree_r3_descriptors(source_root)
    require(
        descriptors == R3_EXACT_DESCRIPTORS,
        f"{route} R3 descriptor surface differs from the signed contract",
    )
    require(
        domain_digest("agent-assure:s1-successor-git-delta/v1", descriptors) == R3_DELTA_DIGEST,
        f"{route} R3 descriptor surface has the wrong delta digest",
    )
    runner_descriptor = next(
        item for item in descriptors if item["path"] == R3_RUNNER_PROTOCOL_IDENTITY["path"]
    )
    runner_path = source_root / R3_RUNNER_PROTOCOL_IDENTITY["path"]
    runner_raw = read_bounded_regular_file(
        runner_path,
        runner_descriptor["bytes"],
        "prospective R3 runner",
    )
    require(
        len(runner_raw) == runner_descriptor["bytes"], "prospective R3 runner byte count mismatch"
    )
    require(
        sha256(runner_raw) == runner_descriptor["sha256"], "prospective R3 runner SHA-256 mismatch"
    )
    validate_r3_runner_protocol_identity(runner_raw, R3_RUNNER_PROTOCOL_IDENTITY)
    module_name = "successor_v3_prospective_r3_json_probe"
    with registered_source_module(
        runner_path,
        module_name,
        "prospective R3 runner JSON compatibility probe",
    ) as runner:
        require(
            callable(getattr(runner, "strict_json_loads", None)),
            "prospective R3 runner lacks strict_json_loads",
        )
        require(
            callable(getattr(runner, "canonical_bytes", None)),
            "prospective R3 runner lacks canonical_bytes",
        )
        require(
            callable(getattr(runner, "_closed_schema_format_checker", None)),
            "prospective R3 runner lacks closed schema-format checking",
        )
        require(
            callable(getattr(runner, "_schema_external_references", None)),
            "prospective R3 runner lacks schema-reference discovery",
        )
        require(
            callable(getattr(runner, "_validate_json_schema", None)),
            "prospective R3 runner lacks schema-instance validation",
        )
        require(bool(json_documents), "prospective R3 runner compatibility document set is empty")
        parsed_documents: dict[str, Any] = {}
        for relative_path, raw in sorted(json_documents.items()):
            safe_relative_path(relative_path)
            try:
                observed = runner.strict_json_loads(raw.decode("utf-8", "strict"))
                observed_canonical = runner.canonical_bytes(observed)
            except Exception as exc:
                raise ValidationError(
                    "prospective package JSON is incompatible with the exact R3 "
                    f"runner at {relative_path}: {type(exc).__name__}: {exc}"
                ) from exc
            expected = parse_json_bytes(
                raw,
                f"prospective R3 runner compatibility document {relative_path}",
            )
            require(
                observed_canonical == canonical(expected),
                "prospective package JSON canonical bytes differ under the exact "
                f"R3 runner at {relative_path}",
            )
            parsed_documents[relative_path] = observed
            if relative_path.endswith(".schema.json"):
                try:
                    runner._closed_schema_format_checker(observed)
                    external_references = runner._schema_external_references(observed)
                except Exception as exc:
                    raise ValidationError(
                        "prospective package schema is incompatible with the exact "
                        f"R3 runner at {relative_path}: {type(exc).__name__}: {exc}"
                    ) from exc
                require(
                    not external_references,
                    "prospective package schema contains an external reference under "
                    f"the exact R3 runner at {relative_path}",
                )
        claim_path = "claims/kickoff.claim"
        claim_schema_path = INSTANCE_SCHEMAS[claim_path]
        require(
            claim_path in parsed_documents and claim_schema_path in parsed_documents,
            "prospective R3 probe lacks the kickoff claim/schema pair",
        )
        try:
            runner._validate_json_schema(
                parsed_documents[claim_path],
                parsed_documents[claim_schema_path],
                owner="prospective kickoff claim",
            )
        except Exception as exc:
            raise ValidationError(
                "prospective kickoff claim fails the exact R3 node-1 schema path: "
                f"{type(exc).__name__}: {exc}"
            ) from exc

        opaque_instance_data_schema = {
            "const": {
                "format": "agent-assure-instance-data/1",
                "$ref": "file:///literal-instance-data",
            },
            "default": {"format": "agent-assure-default-data/1"},
            "examples": [{"$ref": "file:///example-instance-data"}],
            "enum": [{"format": "agent-assure-enum-data/1"}],
        }
        try:
            runner._closed_schema_format_checker(opaque_instance_data_schema)
            opaque_references = runner._schema_external_references(opaque_instance_data_schema)
        except Exception as exc:
            raise ValidationError(
                "prospective R3 runner descends into instance-valued schema keywords: "
                f"{type(exc).__name__}: {exc}"
            ) from exc
        require(
            not opaque_references,
            "prospective R3 runner treats instance-valued $ref data as schema",
        )
        uuid_schema = {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "type": "object",
            "required": ["claim_nonce"],
            "properties": {
                "claim_nonce": {"type": "string", "format": "uuid"},
            },
            "additionalProperties": False,
        }
        try:
            runner._validate_json_schema(
                {"claim_nonce": CLAIM_NONCE},
                uuid_schema,
                owner="prospective canonical-UUID positive control",
            )
        except Exception as exc:
            raise ValidationError(
                f"prospective R3 runner rejected a canonical UUID: {type(exc).__name__}: {exc}"
            ) from exc
        for invalid_uuid in (
            CLAIM_NONCE.upper(),
            CLAIM_NONCE.replace("-", ""),
            "{" + CLAIM_NONCE + "}",
            "not-a-uuid",
        ):
            noncanonical_uuid_rejected = False
            try:
                runner._validate_json_schema(
                    {"claim_nonce": invalid_uuid},
                    uuid_schema,
                    owner="prospective canonical-UUID negative control",
                )
            except Exception as exc:
                noncanonical_uuid_rejected = "schema validation failed" in str(exc)
            require(
                noncanonical_uuid_rejected,
                "prospective R3 runner accepted a noncanonical UUID",
            )
        unsupported_format_rejected = False
        try:
            runner._closed_schema_format_checker(
                {
                    "type": "object",
                    "properties": {"value": {"type": "string", "format": "email"}},
                }
            )
        except Exception as exc:
            unsupported_format_rejected = "unsupported formats" in str(exc) and "email" in str(exc)
        require(
            unsupported_format_rejected,
            "prospective R3 runner accepted a genuine unsupported schema format",
        )
        external_reference_rejected = False
        try:
            runner._validate_json_schema(
                {},
                {"$defs": {"x": {"$ref": "file:///actual-schema-ref"}}},
                owner="prospective external-reference negative control",
            )
        except Exception as exc:
            external_reference_rejected = "nonlocal references" in str(exc)
        require(
            external_reference_rejected,
            "prospective R3 runner accepted a genuine external schema reference",
        )
        negative_rejected = False
        try:
            runner.strict_json_loads('"\\r\\n"')
        except Exception as exc:
            negative_rejected = "control or surrogate character" in str(exc)
        require(negative_rejected, "prospective R3 runner accepted decoded CRLF control characters")


def descriptor(path: Path, root: Path) -> dict[str, Any]:
    assert_no_reparse_chain(path, "descriptor input")
    before = path.lstat()
    require(
        path.is_file() and not path.is_symlink(), f"descriptor input is not a regular file: {path}"
    )
    require(
        before.st_size <= MAX_JSON_FILE_BYTES,
        f"descriptor input exceeds its {MAX_JSON_FILE_BYTES}-byte bound: {path}",
    )
    digest = sha256_file_exact_size(path, before.st_size, "descriptor input").hex()
    after = path.lstat()
    require(
        (before.st_mode, before.st_ino, before.st_size, before.st_mtime_ns)
        == (after.st_mode, after.st_ino, after.st_size, after.st_mtime_ns),
        f"descriptor input changed while hashed: {path}",
    )
    return {
        "path": path.relative_to(root).as_posix(),
        "bytes": before.st_size,
        "sha256": "sha256:" + digest,
    }


def semantic_projection(value: dict[str, Any], field: str) -> dict[str, Any]:
    projection = copy.deepcopy(value)
    require(field in projection, f"missing digest field {field}")
    del projection[field]
    return projection


def validate_own_digest(value: dict[str, Any], field: str) -> None:
    require(isinstance(value.get("digest_domain"), str), f"{field}: digest_domain missing")
    expected = domain_digest(value["digest_domain"], semantic_projection(value, field))
    require(value[field] == expected, f"{field} mismatch: expected {expected}, got {value[field]}")


def safe_relative_path(value: str) -> None:
    require("\\" not in value, f"backslash path rejected: {value}")
    require(not value.startswith("/"), f"absolute path rejected: {value}")
    require(not re.match(r"^[A-Za-z]:", value), f"drive path rejected: {value}")
    parts = PurePosixPath(value).parts
    require(parts and all(part not in {"", ".", ".."} for part in parts), f"unsafe path: {value}")
    reserved = {
        "CON",
        "PRN",
        "AUX",
        "NUL",
        *(f"COM{i}" for i in range(1, 10)),
        *(f"LPT{i}" for i in range(1, 10)),
    }
    for part in parts:
        require(not part.endswith((".", " ")), f"Windows trailing dot/space rejected: {value}")
        require(":" not in part, f"Windows ADS rejected: {value}")
        require(
            part.split(".", 1)[0].upper() not in reserved,
            f"Windows reserved path rejected: {value}",
        )


def exact_entry_surface(root: Path) -> tuple[list[str], list[str]]:
    files: list[str] = []
    directories: list[str] = []
    for path, is_directory in assert_no_reparse_tree(
        root,
        "package",
        maximum_entries=PACKAGE_MAX_TREE_ENTRIES,
    ):
        relative = path.relative_to(root).as_posix()
        safe_relative_path(relative)
        if is_directory:
            require(path.is_dir(), f"package directory changed type: {relative}")
            directories.append(relative)
        else:
            require(path.is_file(), f"package entry is not a regular file: {relative}")
            files.append(relative)
    require(
        len(files) == len(set(item.casefold() for item in files)),
        "package file case-fold collision",
    )
    require(
        len(directories) == len(set(item.casefold() for item in directories)),
        "package directory case-fold collision",
    )
    return sorted(files), sorted(directories)


def parent_directories(paths: Iterable[str]) -> list[str]:
    result: set[str] = set()
    for value in paths:
        parent = PurePosixPath(value).parent
        while parent != PurePosixPath("."):
            result.add(parent.as_posix())
            parent = parent.parent
    return sorted(result)


def exact_edges() -> list[tuple[str, str]]:
    result = [
        (PRE_IDS[0], PRE_IDS[1]),
        (PRE_IDS[1], PRE_IDS[2]),
        (PRE_IDS[2], PRE_IDS[3]),
        (PRE_IDS[3], PRE_IDS[4]),
    ]
    result += [(PRE_IDS[4], target) for target in PRE_IDS[5:10]]
    result += [(source, PRE_IDS[10]) for source in PRE_IDS[5:10]]
    result += [(source, PRE_IDS[11]) for source in PRE_IDS[5:11]]
    return result


def validate_graph(
    graph: dict[str, Any],
    expected_ids: list[str],
    expected_edges: list[tuple[str, str]],
    terminal: str,
) -> None:
    ids = [node["id"] for node in graph["nodes"]]
    require(ids == expected_ids, f"graph node sequence mismatch: {ids!r}")
    require(len(ids) == len(set(ids)), "duplicate graph node ID")
    predicates = [node["predicate"]["id"] for node in graph["nodes"]]
    expected_predicates = PREDICATES[: len(expected_ids)]
    require(predicates == expected_predicates, "graph predicate sequence mismatch")
    for node in graph["nodes"]:
        command_budget = sum(command["max_output_bytes"] for command in node["commands"])
        require(
            all(
                1024 <= command["max_output_bytes"] <= MAX_COMMAND_OUTPUT_BYTES
                for command in node["commands"]
            ),
            f"command output budget is outside the protocol bound: {node['id']}",
        )
        require(
            node["max_combined_output_bytes"] == command_budget,
            f"node aggregate output budget mismatch: {node['id']}",
        )
        require(
            node["max_semantic_output_bytes"] == DEFAULT_SEMANTIC_OUTPUT_BYTES,
            f"node semantic-output budget mismatch: {node['id']}",
        )
    observed_edges = [(edge["from"], edge["to"]) for edge in graph["edges"]]
    require(observed_edges == expected_edges, "graph edge sequence mismatch")
    require(len(observed_edges) == len(set(observed_edges)), "duplicate graph edge")
    require(all(left != right for left, right in observed_edges), "self-loop rejected")
    require(
        all(left in ids and right in ids for left, right in observed_edges), "dangling graph edge"
    )
    require(graph["terminal_node"] == terminal, "graph terminal mismatch")
    expected_output_budget = (
        PRECLOSURE_OUTPUT_BUDGET_BYTES
        if expected_ids == PRE_IDS
        else FULL_CEREMONY_OUTPUT_BUDGET_BYTES
    )
    require(
        graph["max_combined_output_bytes"] == expected_output_budget,
        "graph aggregate output budget mismatch",
    )
    expected_semantic_output_budget = (
        PRECLOSURE_SEMANTIC_OUTPUT_BUDGET_BYTES
        if expected_ids == PRE_IDS
        else FULL_CEREMONY_SEMANTIC_OUTPUT_BUDGET_BYTES
    )
    require(
        graph["max_combined_semantic_output_bytes"] == expected_semantic_output_budget,
        "graph aggregate semantic-output budget mismatch",
    )
    incoming = {node_id: 0 for node_id in ids}
    outgoing: dict[str, list[str]] = {node_id: [] for node_id in ids}
    for left, right in observed_edges:
        incoming[right] += 1
        outgoing[left].append(right)
    require(incoming[ids[0]] == 0, "graph root has predecessor")
    require(all(incoming[node_id] > 0 for node_id in ids[1:]), "orphan graph node")
    queue = [node_id for node_id in ids if incoming[node_id] == 0]
    visited: list[str] = []
    remaining = dict(incoming)
    while queue:
        current = queue.pop(0)
        visited.append(current)
        for target in outgoing[current]:
            remaining[target] -= 1
            if remaining[target] == 0:
                queue.append(target)
    require(len(visited) == len(ids), "graph cycle detected")
    reverse: dict[str, list[str]] = {node_id: [] for node_id in ids}
    for left, right in observed_edges:
        reverse[right].append(left)
    reaches_terminal = {terminal}
    queue = [terminal]
    while queue:
        current = queue.pop()
        for parent in reverse[current]:
            if parent not in reaches_terminal:
                reaches_terminal.add(parent)
                queue.append(parent)
    require(reaches_terminal == set(ids), "node cannot reach terminal")
    projection = {
        "nodes": graph["nodes"],
        "edges": graph["edges"],
        "terminal_node": terminal,
        "max_combined_output_bytes": expected_output_budget,
        "max_combined_semantic_output_bytes": expected_semantic_output_budget,
    }
    require(
        graph["graph_digest"] == domain_digest(graph["digest_domain"], projection),
        "graph digest mismatch",
    )


def git_environment(isolation_root: Path) -> dict[str, str]:
    isolation_root = isolation_root.absolute()
    require(isolation_root.is_dir(), f"Git isolation root is missing: {isolation_root}")
    assert_no_reparse_chain(isolation_root, "Git isolation root")
    home = isolation_root / "home"
    xdg = isolation_root / "xdg"
    child_temp = isolation_root / "temp"
    for directory in (home, xdg, child_temp):
        directory.mkdir(parents=True, exist_ok=True)
        assert_no_reparse_chain(directory, "Git isolation directory")
    return {
        "COMSPEC": r"C:\Windows\System32\cmd.exe",
        "SYSTEMROOT": r"C:\Windows",
        "WINDIR": r"C:\Windows",
        "PATH": r"C:\Program Files\Git\mingw64\bin;C:\Windows\System32\OpenSSH;C:\Windows\System32;C:\Windows",
        "PATHEXT": ".COM;.EXE;.BAT;.CMD",
        "NODEFAULTCURRENTDIRECTORYINEXEPATH": "1",
        "TEMP": str(child_temp),
        "TMP": str(child_temp),
        "HOME": str(home),
        "USERPROFILE": str(home),
        "XDG_CONFIG_HOME": str(xdg),
        "GIT_EXEC_PATH": str(FROZEN_GIT_EXEC_PATH),
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_CONFIG_GLOBAL": "NUL",
        "GIT_TERMINAL_PROMPT": "0",
        "GIT_ATTR_NOSYSTEM": "1",
        "GIT_OPTIONAL_LOCKS": "0",
        "GIT_NO_REPLACE_OBJECTS": "1",
        "GIT_NO_LAZY_FETCH": "1",
        "GIT_SSL_CAINFO": str(FROZEN_GIT_CA_BUNDLE),
        "SSL_CERT_FILE": str(FROZEN_GIT_CA_BUNDLE),
        "OPENSSL_CONF": str(FROZEN_GIT_OPENSSL_CONFIG),
        "OPENSSL_MODULES": str(FROZEN_GIT_OPENSSL_MODULES),
        "GIT_ASKPASS": "",
        "SSH_ASKPASS": "",
        "LC_ALL": "C",
    }


def git_isolation_config_args(isolation_root: Path) -> list[str]:
    """Create exact empty Git policy files; Git 2.54 rejects NUL as excludesFile."""

    hooks = isolation_root / "hooks"
    hooks.mkdir()
    exclude = isolation_root / "global-excludes"
    attributes = isolation_root / "global-attributes"
    for path in (exclude, attributes):
        with path.open("xb") as handle:
            handle.flush()
            os.fsync(handle.fileno())
        assert_no_reparse_chain(path, "Git isolation policy file")
        require(read_bytes(path) == b"", f"Git isolation policy file is not empty: {path}")
    assert_no_reparse_chain(hooks, "Git isolation hooks directory")
    require(not any(hooks.iterdir()), "Git isolation hooks directory is not empty")
    return [
        "-c",
        f"core.hooksPath={hooks}",
        "-c",
        f"core.excludesFile={exclude}",
        "-c",
        f"core.attributesFile={attributes}",
    ]


def assert_no_reparse_tree(
    root: Path,
    owner: str,
    *,
    maximum_entries: int,
) -> list[tuple[Path, bool]]:
    """Return a bounded typed surface; never suppress enumeration errors."""

    assert_no_reparse_chain(root, owner)
    require(
        root.is_dir() and maximum_entries >= 1,
        f"{owner} is not a directory or has an invalid tree-entry bound: {root}",
    )
    pending = [root]
    observed: list[tuple[Path, bool]] = []
    while pending:
        directory = pending.pop()
        try:
            iterator = os.scandir(directory)
        except OSError as exc:
            raise ValidationError(
                f"{owner} cannot be completely enumerated: {directory}: {exc}"
            ) from exc
        with iterator:
            try:
                for entry in iterator:
                    require(
                        len(observed) < maximum_entries,
                        f"{owner} exceeds its {maximum_entries}-entry tree bound",
                    )
                    path = Path(entry.path)
                    try:
                        metadata = path.lstat()
                    except OSError as exc:
                        raise ValidationError(
                            f"{owner} entry cannot be inspected: {path}: {exc}"
                        ) from exc
                    require(
                        not entry.is_symlink()
                        and not bool(
                            getattr(metadata, "st_file_attributes", 0)
                            & stat.FILE_ATTRIBUTE_REPARSE_POINT
                        ),
                        f"{owner} contains a symlink or reparse point: {path}",
                    )
                    is_directory = stat.S_ISDIR(metadata.st_mode)
                    observed.append((path, is_directory))
                    if is_directory:
                        pending.append(path)
            except OSError as exc:
                raise ValidationError(
                    f"{owner} cannot be completely enumerated: {directory}: {exc}"
                ) from exc
    return sorted(
        observed,
        key=lambda row: row[0].relative_to(root).as_posix().encode("utf-8"),
    )


def inventory_rows_from_surface(
    root: Path,
    candidates: list[tuple[Path, bool]],
    *,
    owner: str,
    maximum_size_bytes: int,
    skip_pycache: bool,
    forbidden_suffixes: frozenset[str],
    require_single_link: bool,
) -> list[tuple[str, int, bytes]]:
    """Hash one typed surface with exact byte bounds and stable file metadata."""

    rows: list[tuple[str, int, bytes]] = []
    cumulative_size = 0
    for candidate, is_directory in candidates:
        relative = candidate.relative_to(root)
        before = candidate.lstat()
        require(
            not candidate.is_symlink()
            and not bool(
                getattr(before, "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT
            ),
            f"{owner} contains a symlink or reparse point: {candidate}",
        )
        if is_directory or (skip_pycache and "__pycache__" in relative.parts):
            continue
        require(candidate.is_file(), f"{owner} contains a non-file entry: {candidate}")
        require(
            candidate.suffix.casefold() not in forbidden_suffixes,
            f"{owner} contains a forbidden file: {candidate}",
        )
        if require_single_link:
            require(before.st_nlink == 1, f"{owner} contains a multiply linked file: {candidate}")
        cumulative_size += before.st_size
        require(
            cumulative_size <= maximum_size_bytes,
            f"{owner} exceeds its {maximum_size_bytes}-byte inventory bound",
        )
        raw_hash = sha256_file_exact_size(candidate, before.st_size, owner)
        after = candidate.lstat()
        require(
            (before.st_mode, before.st_ino, before.st_size, before.st_mtime_ns, before.st_nlink)
            == (after.st_mode, after.st_ino, after.st_size, after.st_mtime_ns, after.st_nlink),
            f"{owner} file changed while hashed: {candidate}",
        )
        if require_single_link:
            require(
                after.st_nlink == 1, f"{owner} became multiply linked while hashed: {candidate}"
            )
        rows.append((relative.as_posix(), before.st_size, raw_hash))
    return rows


def raw_local_git_config_names(config_path: Path) -> list[str]:
    raw = read_bytes(config_path)
    require(b"\0" not in raw and b"\r" not in raw, "local Git config contains forbidden bytes")
    try:
        text = raw.decode("utf-8", "strict")
    except UnicodeDecodeError as exc:
        raise ValidationError("local Git config is not strict UTF-8") from exc
    section: str | None = None
    names: list[str] = []
    for number, source_line in enumerate(text.splitlines(), 1):
        line = source_line.strip()
        if not line or line.startswith(("#", ";")):
            continue
        section_match = re.fullmatch(r'\[([A-Za-z0-9.-]+)(?:\s+"([^"\\\r\n]+)")?\]', line)
        if section_match is not None:
            section = section_match.group(1).casefold()
            subsection = section_match.group(2)
            if subsection is not None:
                section += "." + subsection.casefold()
            continue
        require(section is not None, f"local Git config key precedes section at line {number}")
        key_match = re.fullmatch(r"([A-Za-z][A-Za-z0-9-]*)\s*=.*", line)
        require(key_match is not None, f"unsupported local Git config syntax at line {number}")
        assert key_match is not None
        names.append(section + "." + key_match.group(1).casefold())
    return names


def validate_git_index_structure(index: Path) -> None:
    """Require one self-contained v2 SHA-1 index without ambient caches."""

    raw = read_bytes(index)
    require(len(raw) >= 32 and raw[:4] == b"DIRC", "Git index header is invalid")
    require(
        int.from_bytes(raw[4:8], "big") == 2,
        "Git index must use the exact self-contained v2 format",
    )
    require(hashlib.sha1(raw[:-20]).digest() == raw[-20:], "Git index checksum mismatch")
    entry_count = int.from_bytes(raw[8:12], "big")
    offset = 12
    payload_end = len(raw) - 20
    for ordinal in range(entry_count):
        require(offset + 62 <= payload_end, f"Git index entry {ordinal + 1} is truncated")
        flags = int.from_bytes(raw[offset + 60 : offset + 62], "big")
        require(
            not flags & 0xF000,
            "Git index entry uses assume-valid, extended, or nonzero merge-stage flags",
        )
        name_end = raw.find(b"\0", offset + 62, payload_end)
        require(name_end >= 0, f"Git index entry {ordinal + 1} lacks a path terminator")
        name_length = name_end - (offset + 62)
        require(
            (flags & 0x0FFF) == min(name_length, 0x0FFF),
            f"Git index entry {ordinal + 1} pathname-length flags are inconsistent",
        )
        entry_bytes = name_end + 1 - offset
        offset += (entry_bytes + 7) & ~7
        require(offset <= payload_end, f"Git index entry {ordinal + 1} padding is truncated")
    forbidden_extensions = {b"FSMN", b"UNTR", b"link"}
    while offset < payload_end:
        require(offset + 8 <= payload_end, "Git index extension header is truncated")
        signature = raw[offset : offset + 4]
        size = int.from_bytes(raw[offset + 4 : offset + 8], "big")
        offset += 8
        require(offset + size <= payload_end, "Git index extension payload is truncated")
        require(
            signature not in forbidden_extensions,
            f"forbidden mutable/indirect Git index extension: {signature!r}",
        )
        offset += size
    require(offset == payload_end, "Git index has trailing unparsed bytes")


def preflight_git_administration(
    repository: Path,
    *,
    no_checkout_clone: bool = False,
    empty_template_bootstrap: bool = False,
) -> None:
    git_dir = repository / ".git"
    assert_no_reparse_chain(repository, "repository root")
    assert_no_reparse_chain(git_dir, "repository Git directory")
    require(
        git_dir.is_dir() and not git_dir.is_symlink(),
        "ordinary sole-worktree .git directory required",
    )
    for required in [git_dir / "config", git_dir / "HEAD"]:
        assert_no_reparse_chain(required, "Git administrative surface")
    exclude = git_dir / "info" / "exclude"
    if empty_template_bootstrap:
        assert_no_reparse_chain(
            exclude.parent, "empty-template Git info parent", require_exists=False
        )
        require(
            not exclude.exists() and not exclude.is_symlink(),
            "empty-template bootstrap unexpectedly has .git/info/exclude",
        )
    else:
        assert_no_reparse_chain(exclude, "Git administrative surface")
    index = git_dir / "index"
    if no_checkout_clone:
        require(
            not index.exists() and not index.is_symlink(),
            "no-checkout clone unexpectedly has a Git index before detached checkout",
        )
    else:
        assert_no_reparse_chain(index, "Git administrative surface")
        validate_git_index_structure(index)
    git_surface = assert_no_reparse_tree(
        git_dir,
        "Git administrative tree",
        maximum_entries=REPOSITORY_MAX_TREE_ENTRIES,
    )
    top_level_locks = [
        git_dir / "index.lock",
        git_dir / "HEAD.lock",
        git_dir / "config.lock",
        git_dir / "packed-refs.lock",
    ]
    require(
        not any(path.exists() or path.is_symlink() for path in top_level_locks),
        "Git administrative lockfile is active or stale",
    )
    require(
        not any(path.name.casefold().endswith(".lock") for path, _ in git_surface),
        "Git administrative lockfile is active or stale",
    )
    require(
        not any(
            path.parent == git_dir and path.name.casefold().startswith("sharedindex.")
            for path, _ in git_surface
        ),
        "split-index shared state is forbidden",
    )
    operation_markers = [
        git_dir / "MERGE_HEAD",
        git_dir / "CHERRY_PICK_HEAD",
        git_dir / "REVERT_HEAD",
        git_dir / "REBASE_HEAD",
        git_dir / "AUTO_MERGE",
        git_dir / "rebase-apply",
        git_dir / "rebase-merge",
        git_dir / "sequencer",
        git_dir / "BISECT_LOG",
        git_dir / "BISECT_START",
        git_dir / "BISECT_TERMS",
        git_dir / "BISECT_NAMES",
    ]
    require(
        not any(path.exists() or path.is_symlink() for path in operation_markers),
        "an in-progress Git merge/rebase/cherry-pick/revert/bisect/sequencer operation is forbidden",
    )
    for forbidden in [
        git_dir / "commondir",
        git_dir / "config.worktree",
        git_dir / "shallow",
        git_dir / "worktrees",
        git_dir / "info" / "grafts",
        git_dir / "objects" / "info" / "alternates",
        git_dir / "objects" / "info" / "http-alternates",
    ]:
        require(
            not forbidden.exists() and not forbidden.is_symlink(),
            f"forbidden Git indirection: {forbidden}",
        )
    names = raw_local_git_config_names(git_dir / "config")
    dangerous_exact = {
        "core.fsmonitor",
        "core.untrackedcache",
        "core.attributesfile",
        "core.excludesfile",
        "core.hookspath",
        "core.sshcommand",
        "core.gitproxy",
        "core.alternaterefscommand",
        "core.worktree",
        "core.sparsecheckout",
        "uploadpack.packobjectshook",
        "core.splitindex",
        "extensions.worktreeconfig",
        "extensions.partialclone",
        "index.sparse",
    }
    require(
        not any(
            name in dangerous_exact
            or name.startswith(
                (
                    "include.",
                    "includeif.",
                    "filter.",
                    "fsck.",
                    "fetch.fsck.",
                    "receive.fsck.",
                    "http.",
                    "credential.",
                    "url.",
                    "protocol.",
                    "extensions.",
                )
            )
            or (
                name.startswith("remote.")
                and name.endswith(
                    (
                        ".promisor",
                        ".partialclonefilter",
                        ".uploadpack",
                        ".pushurl",
                        ".proxy",
                        ".receivepack",
                    )
                )
            )
            or (name.startswith("diff.") and name.endswith((".textconv", ".command", ".external")))
            or (name.startswith("merge.") and name.endswith(".driver"))
            or (name.startswith("submodule.") and name.endswith(".update"))
            for name in names
        ),
        "mutable, executable, sparse, included, or lazy-fetch local Git configuration rejected",
    )


def frozen_git_delegate_identity() -> dict[str, Any]:
    assert_no_reparse_chain(FROZEN_GIT_EXEC_PATH, "frozen Git exec path")
    require(
        FROZEN_GIT_EXEC_PATH.is_dir(), f"frozen Git exec path is missing: {FROZEN_GIT_EXEC_PATH}"
    )
    delegates: dict[str, dict[str, Any]] = {}
    for role, path, expected_bytes, expected_sha256 in [
        ("https_transport", FROZEN_GIT_HTTPS, FROZEN_GIT_HTTPS_BYTES, FROZEN_GIT_HTTPS_SHA256),
        (
            "upload_pack",
            FROZEN_GIT_UPLOAD_PACK,
            FROZEN_GIT_UPLOAD_PACK_BYTES,
            FROZEN_GIT_UPLOAD_PACK_SHA256,
        ),
    ]:
        assert_no_reparse_chain(path, f"frozen Git {role}")
        raw = read_bounded_regular_file(path, expected_bytes, f"frozen Git {role}")
        require(
            len(raw) == expected_bytes and hashlib.sha256(raw).hexdigest() == expected_sha256,
            f"frozen Git {role} identity mismatch",
        )
        delegates[role] = {
            "path": str(path),
            "bytes": len(raw),
            "sha256": sha256(raw),
        }
    require(
        os.path.samefile(FROZEN_GIT, FROZEN_GIT_UPLOAD_PACK),
        "frozen Git upload-pack is not the exact hard-linked Git executable",
    )
    return {"exec_path": str(FROZEN_GIT_EXEC_PATH), **delegates}


def git_runtime_inventory() -> dict[str, Any]:
    """Bind the complete Git-for-Windows runtime, including DLL/TLS/shell closure."""

    root = GIT_RUNTIME_ROOT.absolute()
    assert_no_reparse_chain(root, "frozen Git runtime")
    require(root.is_dir(), f"frozen Git runtime root is missing: {root}")
    candidates = assert_no_reparse_tree(
        root,
        "frozen Git runtime",
        maximum_entries=GIT_RUNTIME_MAX_TREE_ENTRIES,
    )
    rows = inventory_rows_from_surface(
        root,
        candidates,
        owner="frozen Git runtime",
        maximum_size_bytes=GIT_RUNTIME_SIZE_BYTES,
        skip_pycache=False,
        forbidden_suffixes=frozenset(),
        require_single_link=False,
    )
    final_candidates = assert_no_reparse_tree(
        root,
        "frozen Git runtime final pass",
        maximum_entries=GIT_RUNTIME_MAX_TREE_ENTRIES,
    )
    require(
        [(path.relative_to(root), kind) for path, kind in candidates]
        == [(path.relative_to(root), kind) for path, kind in final_candidates],
        "frozen Git runtime surface changed while inventoried",
    )
    final_rows = inventory_rows_from_surface(
        root,
        final_candidates,
        owner="frozen Git runtime final pass",
        maximum_size_bytes=GIT_RUNTIME_SIZE_BYTES,
        skip_pycache=False,
        forbidden_suffixes=frozenset(),
        require_single_link=False,
    )
    require(
        final_rows == rows, "frozen Git runtime bytes changed between complete inventory passes"
    )
    require(rows, f"frozen Git runtime inventory is empty: {root}")
    digest = hashlib.sha256(GIT_RUNTIME_INVENTORY_DOMAIN)
    for relative, size, raw_hash in sorted(rows, key=lambda row: row[0].encode("utf-8")):
        encoded = relative.encode("utf-8")
        digest.update(len(encoded).to_bytes(8, "big"))
        digest.update(encoded)
        digest.update(size.to_bytes(8, "big"))
        digest.update(raw_hash)
    value = {
        "root": str(root),
        "file_count": len(rows),
        "size_bytes": sum(row[1] for row in rows),
        "digest_domain": GIT_RUNTIME_INVENTORY_DOMAIN[:-1].decode("ascii"),
        "sha256": "sha256:" + digest.hexdigest(),
    }
    require(
        (value["file_count"], value["size_bytes"], value["sha256"])
        == (GIT_RUNTIME_FILE_COUNT, GIT_RUNTIME_SIZE_BYTES, "sha256:" + GIT_RUNTIME_SHA256),
        "frozen Git runtime inventory mismatch",
    )
    return value


def frozen_git_runtime_identity() -> dict[str, Any]:
    delegates = frozen_git_delegate_identity()
    for path, owner, expect_directory in [
        (FROZEN_GIT_CA_BUNDLE, "Git OpenSSL CA bundle", False),
        (FROZEN_GIT_OPENSSL_CONFIG, "Git OpenSSL configuration", False),
        (FROZEN_GIT_OPENSSL_MODULES, "Git OpenSSL module directory", True),
    ]:
        assert_no_reparse_chain(path, owner)
        require(
            path.is_dir() if expect_directory else path.is_file(), f"{owner} is missing: {path}"
        )
    return {
        "runtime_inventory": git_runtime_inventory(),
        **delegates,
        "tls": {
            "backend": "openssl",
            "ca_bundle": str(FROZEN_GIT_CA_BUNDLE),
            "openssl_config": str(FROZEN_GIT_OPENSSL_CONFIG),
            "openssl_modules": str(FROZEN_GIT_OPENSSL_MODULES),
        },
    }


_PROCESS_GIT_RUNTIME_IDENTITY: dict[str, Any] | None = None


def attest_process_git_runtime() -> dict[str, Any]:
    """Hash the full Git closure once before the first local Git call in this process."""

    global _PROCESS_GIT_RUNTIME_IDENTITY
    if _PROCESS_GIT_RUNTIME_IDENTITY is None:
        _PROCESS_GIT_RUNTIME_IDENTITY = frozen_git_runtime_identity()
    return copy.deepcopy(_PROCESS_GIT_RUNTIME_IDENTITY)


def source_git_runtime_binding(identity: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "inventory": copy.deepcopy(identity["runtime_inventory"]),
        "exec_path": identity["exec_path"],
        "tls": copy.deepcopy(identity["tls"]),
    }


def run_git_result(repository: Path, *args: str) -> subprocess.CompletedProcess[bytes]:
    attest_process_git_runtime()
    require(FROZEN_GIT.is_file(), f"frozen Git missing: {FROZEN_GIT}")
    git_bytes = read_bytes(FROZEN_GIT)
    require(
        len(git_bytes) == FROZEN_GIT_BYTES
        and hashlib.sha256(git_bytes).hexdigest() == FROZEN_GIT_SHA256,
        "frozen Git identity mismatch",
    )
    with tempfile.TemporaryDirectory(
        prefix="agent-assure-v3-local-git-",
        dir=os.environ["TEMP"],
    ) as isolation_text:
        isolation_root = Path(isolation_text)
        execution_root = isolation_root / "cwd"
        execution_root.mkdir()
        result, timed_out, output_exceeded = run_windows_job_bounded(
            [
                str(FROZEN_GIT),
                "--no-replace-objects",
                f"--git-dir={repository / '.git'}",
                f"--work-tree={repository}",
                *git_isolation_config_args(isolation_root),
                "-c",
                "core.fsmonitor=false",
                "-c",
                "core.untrackedCache=false",
                "-c",
                "credential.helper=",
                "-c",
                "submodule.recurse=false",
                *args,
            ],
            cwd=execution_root,
            environment=git_environment(isolation_root),
            timeout_seconds=1_800,
            max_output_bytes=MAX_COMMAND_OUTPUT_BYTES,
            stdout_path=isolation_root / "stdout.bin",
            stderr_path=isolation_root / "stderr.bin",
        )
    require(not timed_out, "local Git process tree exceeded 1800 seconds and was terminated")
    require(
        not output_exceeded,
        "local Git process tree exceeded its 16 MiB output budget and was terminated",
    )
    return result


def run_git_input_result(
    repository: Path,
    input_bytes: bytes,
    *args: str,
) -> subprocess.CompletedProcess[bytes]:
    attest_process_git_runtime()
    require(FROZEN_GIT.is_file(), f"frozen Git missing: {FROZEN_GIT}")
    git_bytes = read_bytes(FROZEN_GIT)
    require(
        len(git_bytes) == FROZEN_GIT_BYTES
        and hashlib.sha256(git_bytes).hexdigest() == FROZEN_GIT_SHA256,
        "frozen Git identity mismatch",
    )
    with tempfile.TemporaryDirectory(
        prefix="agent-assure-v3-local-git-input-",
        dir=os.environ["TEMP"],
    ) as isolation_text:
        isolation_root = Path(isolation_text)
        execution_root = isolation_root / "cwd"
        execution_root.mkdir()
        require(
            len(input_bytes) <= MAX_EMBEDDED_BLOB_BYTES,
            "local Git stdin exceeds its 16 MiB fixed bound",
        )
        result, timed_out, output_exceeded = run_windows_job_bounded(
            [
                str(FROZEN_GIT),
                "--no-replace-objects",
                f"--git-dir={repository / '.git'}",
                f"--work-tree={repository}",
                *git_isolation_config_args(isolation_root),
                "-c",
                "core.fsmonitor=false",
                "-c",
                "core.untrackedCache=false",
                "-c",
                "credential.helper=",
                "-c",
                "submodule.recurse=false",
                *args,
            ],
            cwd=execution_root,
            environment=git_environment(isolation_root),
            timeout_seconds=1_800,
            max_output_bytes=MAX_COMMAND_OUTPUT_BYTES,
            stdout_path=isolation_root / "stdout.bin",
            stderr_path=isolation_root / "stderr.bin",
            stdin_bytes=input_bytes,
        )
    require(not timed_out, "local Git process tree exceeded 1800 seconds and was terminated")
    require(
        not output_exceeded,
        "local Git process tree exceeded its 16 MiB output budget and was terminated",
    )
    return result


def run_frozen_git_external(cwd: Path, *args: str) -> subprocess.CompletedProcess[bytes]:
    assert_no_reparse_chain(cwd, "external Git requested working-directory parent")
    raw = read_bytes(FROZEN_GIT)
    require(
        len(raw) == FROZEN_GIT_BYTES and hashlib.sha256(raw).hexdigest() == FROZEN_GIT_SHA256,
        "frozen Git identity mismatch",
    )
    runtime_before = frozen_git_runtime_identity()
    with tempfile.TemporaryDirectory(
        prefix="agent-assure-v3-external-git-",
        dir=os.environ["TEMP"],
    ) as isolation_text:
        isolation_root = Path(isolation_text)
        execution_root = isolation_root / "cwd"
        execution_root.mkdir()
        result, timed_out, output_exceeded = run_windows_job_bounded(
            [
                str(FROZEN_GIT),
                "--no-replace-objects",
                *git_isolation_config_args(isolation_root),
                "-c",
                "core.fsmonitor=false",
                "-c",
                "core.untrackedCache=false",
                "-c",
                "credential.helper=",
                "-c",
                "submodule.recurse=false",
                "-c",
                "http.sslBackend=openssl",
                "-c",
                f"http.sslCAInfo={FROZEN_GIT_CA_BUNDLE}",
                *args,
            ],
            cwd=execution_root,
            environment=git_environment(isolation_root),
            timeout_seconds=1_800,
            max_output_bytes=MAX_COMMAND_OUTPUT_BYTES,
            stdout_path=isolation_root / "stdout.bin",
            stderr_path=isolation_root / "stderr.bin",
        )
    require(
        frozen_git_runtime_identity() == runtime_before,
        "frozen Git runtime identity changed during external operation",
    )
    require(not timed_out, "external Git process tree exceeded 1800 seconds and was terminated")
    require(
        not output_exceeded,
        "external Git process tree exceeded its 16 MiB output budget and was terminated",
    )
    return result


def run_git_bytes(repository: Path, *args: str) -> bytes:
    result = run_git_result(repository, *args)
    require(
        result.returncode == 0, f"git failed: {args!r}: {result.stderr.decode('utf-8', 'replace')}"
    )
    return result.stdout


def run_git(repository: Path, *args: str) -> str:
    result_bytes = run_git_bytes(repository, *args)
    return result_bytes.decode("utf-8", "strict").rstrip("\n")


def require_direct_ref(repository: Path, ref_name: str, expected_oid: str, label: str) -> None:
    """Require an exact direct ref, never a symbolic alias resolving to the same object."""
    require(
        re.fullmatch(r"refs/(heads|tags)/[A-Za-z0-9._/-]+", ref_name) is not None,
        f"{label} ref name is not canonical",
    )
    require(
        re.fullmatch(r"[0-9a-f]{40}", expected_oid) is not None,
        f"{label} expected object ID is not canonical SHA-1",
    )
    symbolic = run_git_result(repository, "symbolic-ref", "--quiet", ref_name)
    require(symbolic.returncode == 1, f"{label} must be a direct ref, not a symbolic alias")
    observed = run_git_result(repository, "show-ref", "--verify", "--hash", ref_name)
    require(
        observed.returncode == 0
        and observed.stdout.decode("ascii", "strict").rstrip("\n") == expected_oid,
        f"{label} direct object identity mismatch",
    )


def require_exact_absent_ref(repository: Path, ref_name: str, label: str) -> None:
    """Require that a ref is absent, including absence as a dangling symbolic ref."""
    require(
        re.fullmatch(r"refs/(heads|tags)/[A-Za-z0-9._/-]+", ref_name) is not None,
        f"{label} ref name is not canonical",
    )
    symbolic = run_git_result(repository, "symbolic-ref", "--quiet", ref_name)
    require(symbolic.returncode == 1, f"{label} exists as a symbolic ref or cannot be inspected")
    observed = run_git_result(repository, "show-ref", "--verify", "--quiet", ref_name)
    require(
        observed.returncode == 1 and observed.stdout == b"" and observed.stderr == b"",
        f"{label} exists as a direct ref or cannot be inspected",
    )


def successor_branch_initialization_transaction(
    source_ref: str,
    successor_ref: str,
    b3: str,
) -> bytes:
    """Encode the sole permitted atomic symbolic-HEAD transition.

    The old symbolic target is the transaction's compare-and-swap predicate.
    A separate direct verification of ``source_ref`` must not be queued because
    Git treats it as an update through HEAD's referent and rejects the duplicate.
    """
    require(
        re.fullmatch(r"refs/heads/[A-Za-z0-9._/-]+", source_ref) is not None
        and re.fullmatch(r"refs/heads/[A-Za-z0-9._/-]+", successor_ref) is not None
        and source_ref != successor_ref,
        "successor branch transaction ref names are invalid",
    )
    require(
        re.fullmatch(r"[0-9a-f]{40}", b3) is not None and b3 != "0" * 40,
        "successor branch transaction object ID is invalid",
    )
    return (
        "start\n"
        "option no-deref\n"
        f"create {successor_ref} {b3}\n"
        "option no-deref\n"
        f"symref-update HEAD {successor_ref} ref {source_ref}\n"
        "prepare\ncommit\n"
    ).encode("ascii")


def direct_ref_transaction(*operations: tuple[str, ...]) -> bytes:
    """Encode a typed, no-deref transaction containing only direct-ref commands."""
    require(bool(operations), "direct-ref transaction is empty")
    seen: set[str] = set()
    lines = ["start"]
    for operation in operations:
        require(bool(operation), "direct-ref transaction operation is empty")
        action = operation[0]
        expected_length = {"create": 3, "update": 4, "delete": 3, "verify": 3}.get(action)
        require(
            expected_length is not None and len(operation) == expected_length,
            "direct-ref transaction operation shape is invalid",
        )
        ref_name = operation[1]
        require(
            ref_name != "HEAD"
            and re.fullmatch(r"refs/(heads|tags)/[A-Za-z0-9._/-]+", ref_name) is not None,
            "direct-ref transaction ref name is invalid",
        )
        require(ref_name not in seen, "direct-ref transaction repeats a ref")
        seen.add(ref_name)
        for oid in operation[2:]:
            require(
                re.fullmatch(r"[0-9a-f]{40}", oid) is not None and oid != "0" * 40,
                "direct-ref transaction object ID is invalid",
            )
        lines.extend(["option no-deref", " ".join(operation)])
    lines.extend(["prepare", "commit", ""])
    return "\n".join(lines).encode("ascii")


def run_exact_ref_transaction(
    repository: Path,
    payload: bytes,
    label: str,
    *,
    reflog_reason: str,
) -> None:
    require(
        re.fullmatch(r"[ -~]{1,160}", reflog_reason) is not None,
        f"{label} reflog reason is invalid",
    )
    result = run_git_input_result(
        repository,
        payload,
        "update-ref",
        "-m",
        reflog_reason,
        "--stdin",
    )
    require(
        result.returncode == 0
        and result.stdout == b"start: ok\nprepare: ok\ncommit: ok\n"
        and result.stderr == b"",
        f"{label} failed: exit={result.returncode}; "
        f"stdout={result.stdout.decode('utf-8', 'replace')!r}; "
        f"stderr={result.stderr.decode('utf-8', 'replace')!r}",
    )


def require_exact_attached_direct_head(
    repository: Path,
    branch_ref: str,
    oid: str,
    label: str,
) -> None:
    require_direct_ref(repository, branch_ref, oid, f"{label} branch")
    symbolic = run_git_result(repository, "symbolic-ref", "--quiet", "HEAD")
    require(
        symbolic.returncode == 0
        and symbolic.stdout.decode("ascii", "strict").rstrip("\n") == branch_ref,
        f"{label} HEAD symbolic target mismatch",
    )
    require(
        run_git(repository, "rev-parse", "HEAD^{commit}") == oid,
        f"{label} HEAD object identity mismatch",
    )


def find_repository(package: Path) -> Path:
    cursor = package.absolute()
    while cursor != cursor.parent:
        if (cursor / ".git").is_dir():
            preflight_git_administration(cursor)
            return cursor
        cursor = cursor.parent
    raise ValidationError("repository root not found")


class MutationGuard:
    def __init__(self) -> None:
        self.armed = False


_ACTIVE_MUTATION_GUARD: contextvars.ContextVar[MutationGuard | None] = contextvars.ContextVar(
    "successor_v3_active_mutation_guard",
    default=None,
)


def windows_process_creation_filetime(process_id: int) -> int | None:
    """Return the Windows process creation FILETIME, or None if the PID is absent."""
    require(os.name == "nt", "successor transaction liveness requires Windows")
    require(
        isinstance(process_id, int) and 0 < process_id <= 0xFFFFFFFF,
        "successor transaction process ID is invalid",
    )
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    open_process = kernel32.OpenProcess
    open_process.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    open_process.restype = wintypes.HANDLE
    get_process_times = kernel32.GetProcessTimes
    get_process_times.argtypes = [
        wintypes.HANDLE,
        ctypes.POINTER(wintypes.FILETIME),
        ctypes.POINTER(wintypes.FILETIME),
        ctypes.POINTER(wintypes.FILETIME),
        ctypes.POINTER(wintypes.FILETIME),
    ]
    get_process_times.restype = wintypes.BOOL
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = [wintypes.HANDLE]
    close_handle.restype = wintypes.BOOL
    handle = open_process(0x1000, False, process_id)  # PROCESS_QUERY_LIMITED_INFORMATION
    if not handle:
        error = ctypes.get_last_error()
        if error == 87:  # ERROR_INVALID_PARAMETER: no such process
            return None
        raise ValidationError(
            f"cannot establish transaction-owner liveness for PID {process_id}: WinError {error}"
        )
    creation = wintypes.FILETIME()
    exit_time = wintypes.FILETIME()
    kernel = wintypes.FILETIME()
    user = wintypes.FILETIME()
    try:
        if not get_process_times(
            handle,
            ctypes.byref(creation),
            ctypes.byref(exit_time),
            ctypes.byref(kernel),
            ctypes.byref(user),
        ):
            raise ValidationError(
                f"cannot read transaction-owner creation time for PID {process_id}: "
                f"WinError {ctypes.get_last_error()}"
            )
        return (creation.dwHighDateTime << 32) | creation.dwLowDateTime
    finally:
        require(bool(close_handle(handle)), "failed to close transaction-owner process handle")


def windows_atomic_rename_no_replace(source: Path, destination: Path) -> None:
    """Atomically install one same-volume file without replacing a peer's lock."""
    require(os.name == "nt", "successor transaction lock installation requires Windows")
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    move_file_ex = kernel32.MoveFileExW
    move_file_ex.argtypes = [wintypes.LPCWSTR, wintypes.LPCWSTR, wintypes.DWORD]
    move_file_ex.restype = wintypes.BOOL
    if move_file_ex(str(source), str(destination), 0x8):  # MOVEFILE_WRITE_THROUGH
        return
    error = ctypes.get_last_error()
    if error in {80, 183}:  # ERROR_FILE_EXISTS / ERROR_ALREADY_EXISTS
        raise FileExistsError(
            error, "destination transaction lock already exists", str(destination)
        )
    raise OSError(error, "atomic transaction-lock installation failed", str(destination))


def windows_atomic_replace(source: Path, destination: Path) -> None:
    """Atomically replace one same-volume regular file with another."""
    require(os.name == "nt", "successor transaction lock adoption requires Windows")
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    replace_file = kernel32.ReplaceFileW
    replace_file.argtypes = [
        wintypes.LPCWSTR,
        wintypes.LPCWSTR,
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.LPVOID,
    ]
    replace_file.restype = wintypes.BOOL
    if replace_file(str(destination), str(source), None, 0, None, None):
        return
    error = ctypes.get_last_error()
    raise OSError(error, "atomic transaction-lock adoption failed", str(destination))


@contextmanager
def windows_exclusive_file_lock(path: Path) -> Iterable[None]:
    """Elect one cross-session recovery owner on the exact stale lock file."""
    require(
        path.is_absolute() and path.exists() and path.is_file() and not path.is_symlink(),
        "publication recovery election target is not an exact regular file",
    )
    assert_no_reparse_chain(path.parent, "publication recovery election parent")
    require(
        path.lstat().st_nlink == 1, "publication recovery election target must be single-linked"
    )

    class Overlapped(ctypes.Structure):
        _fields_ = [
            ("Internal", ctypes.c_size_t),
            ("InternalHigh", ctypes.c_size_t),
            ("Offset", wintypes.DWORD),
            ("OffsetHigh", wintypes.DWORD),
            ("hEvent", wintypes.HANDLE),
        ]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = [
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.HANDLE,
    ]
    create_file.restype = wintypes.HANDLE
    lock_file = kernel32.LockFileEx
    lock_file.argtypes = [
        wintypes.HANDLE,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.DWORD,
        ctypes.POINTER(Overlapped),
    ]
    lock_file.restype = wintypes.BOOL
    unlock_file = kernel32.UnlockFileEx
    unlock_file.argtypes = [
        wintypes.HANDLE,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.DWORD,
        ctypes.POINTER(Overlapped),
    ]
    unlock_file.restype = wintypes.BOOL
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = [wintypes.HANDLE]
    close_handle.restype = wintypes.BOOL

    handle = create_file(
        str(path),
        0x80000000,  # GENERIC_READ
        0x1 | 0x2 | 0x4,  # FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE
        None,
        3,  # OPEN_EXISTING
        0x80 | 0x00200000,  # FILE_ATTRIBUTE_NORMAL | FILE_FLAG_OPEN_REPARSE_POINT
        None,
    )
    if handle == ctypes.c_void_p(-1).value:
        raise ValidationError(
            f"cannot open publication recovery election target: WinError {ctypes.get_last_error()}"
        )
    overlapped = Overlapped()
    # Lock one byte at offset 2^40, far beyond every canonical JSON lock file.
    # Windows permits byte-range locks beyond EOF; using a non-overlapping
    # range keeps canonical-path rereads available while still electing on the
    # exact file object across processes and Windows sessions.
    overlapped.Offset = 0
    overlapped.OffsetHigh = 0x100
    acquired = False
    try:
        if not lock_file(
            handle,
            0x1 | 0x2,  # LOCKFILE_FAIL_IMMEDIATELY | LOCKFILE_EXCLUSIVE_LOCK
            0,
            1,
            0,
            ctypes.byref(overlapped),
        ):
            error = ctypes.get_last_error()
            if error == 33:  # ERROR_LOCK_VIOLATION
                raise ValidationError(
                    "another publication recovery owns the cross-session filesystem election"
                )
            raise ValidationError(
                f"publication recovery filesystem election failed: WinError {error}"
            )
        acquired = True
        require(
            bool(read_bytes(path)),
            "publication recovery election target became unreadable after acquisition",
        )
        yield
    finally:
        unlock_ok = True
        if acquired:
            unlock_ok = bool(unlock_file(handle, 0, 1, 0, ctypes.byref(overlapped)))
        close_ok = bool(close_handle(handle))
        require(unlock_ok, "failed to release publication recovery filesystem election")
        require(close_ok, "failed to close publication recovery election handle")


def arm_mutation_transaction() -> None:
    guard = _ACTIVE_MUTATION_GUARD.get()
    require(guard is not None, "mutation side effect attempted outside a transaction")
    guard.armed = True


def arm_mutation_transaction_if_active() -> None:
    guard = _ACTIVE_MUTATION_GUARD.get()
    if guard is not None:
        guard.armed = True


@contextmanager
def mutation_transaction(repository: Path, operation: str) -> Iterable[MutationGuard]:
    parent = repository / ".tmp" / "s1-acceptance"
    for directory in [repository / ".tmp", parent]:
        if not directory.exists() and not directory.is_symlink():
            assert_no_reparse_chain(directory.parent, "successor transaction ancestor")
            try:
                directory.mkdir()
            except FileExistsError:
                pass
    assert_no_reparse_chain(parent, "successor transaction parent")
    require(parent.is_dir(), "successor transaction parent is missing")
    lock = parent / f"successor-v3-transaction-{PACKAGE_ID}.lock"
    require(
        not lock.exists() and not lock.is_symlink(),
        "another successor-v3 mutation is active or requires recovery",
    )
    process_id = os.getpid()
    process_started_filetime = windows_process_creation_filetime(process_id)
    require(
        process_started_filetime is not None,
        "current successor transaction process disappeared during lock construction",
    )
    lock_value = {
        "format": CURRENT_MUTATION_LOCK_FORMAT,
        "operation": operation,
        "process_id": process_id,
        "process_started_filetime_100ns": str(process_started_filetime),
        "created_at_utc": utc_text(dt.datetime.now(dt.timezone.utc)),
        "recovery": "follow the README recovery decision table; never delete blindly",
    }
    validate_decoded_json_value(lock_value)
    payload = (
        json.dumps(
            lock_value,
            ensure_ascii=False,
            indent=2,
        )
        + "\n"
    ).encode("utf-8")
    temporary_lock = parent / f".{lock.name}.{uuid.uuid4().hex}.tmp"
    guard = MutationGuard()
    completed = False
    lock_installed = False
    try:
        with temporary_lock.open("xb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        try:
            windows_atomic_rename_no_replace(temporary_lock, lock)
        except FileExistsError as exc:
            raise ValidationError(
                "another successor-v3 mutation became active or requires recovery"
            ) from exc
        lock_installed = True
        require(
            read_bytes(lock) == payload,
            "atomically installed successor transaction lock bytes changed",
        )
        yield guard
        completed = True
    finally:
        if temporary_lock.exists() or temporary_lock.is_symlink():
            require(
                temporary_lock.is_file() and not temporary_lock.is_symlink(),
                "successor transaction temporary lock changed type",
            )
            temporary_lock.unlink()
        # Before arming, a failure is proven to have occurred during read-only
        # preflight and the authentic lock is removed.  Once the operation
        # explicitly arms immediately before its first governed side effect,
        # every exceptional exit retains the lock for audited recovery.
        if lock_installed and (completed or not guard.armed):
            require(
                lock.exists() and not lock.is_symlink(),
                "successor transaction lock disappeared or changed type during mutation",
            )
            require(
                read_bytes(lock) == payload,
                "successor transaction lock bytes changed during mutation",
            )
            lock.unlink()


def transactional_mutation(function: Any) -> Any:
    @functools.wraps(function)
    def wrapper(args: argparse.Namespace) -> dict[str, Any]:
        repository = find_repository(args.package.absolute())
        git_runtime_before = attest_process_git_runtime()
        with mutation_transaction(repository, function.__name__) as guard:
            token = _ACTIVE_MUTATION_GUARD.set(guard)
            try:
                result = function(args)
            finally:
                _ACTIVE_MUTATION_GUARD.reset(token)
                require(
                    frozen_git_runtime_identity() == git_runtime_before,
                    "frozen Git runtime identity changed during governed mutation",
                )
        return result

    return wrapper


def exact_commit_parents(repository: Path, oid: str) -> list[str]:
    line = run_git(repository, "rev-list", "--parents", "-n", "1", oid)
    fields = line.split()
    require(fields and fields[0] == oid, f"commit identity changed while reading parents: {oid}")
    return fields[1:]


def new_york_git_offset(committed_at: dt.datetime) -> str:
    utc_value = committed_at.astimezone(dt.timezone.utc)
    year = utc_value.year
    require(year >= 2007, "successor commit predates the governed modern US daylight-saving rules")
    march_first = dt.date(year, 3, 1)
    march_first_sunday = 1 + (6 - march_first.weekday()) % 7
    march_second_sunday = march_first_sunday + 7
    november_first = dt.date(year, 11, 1)
    november_first_sunday = 1 + (6 - november_first.weekday()) % 7
    dst_start = dt.datetime(year, 3, march_second_sunday, 7, tzinfo=dt.timezone.utc)
    dst_end = dt.datetime(year, 11, november_first_sunday, 6, tzinfo=dt.timezone.utc)
    return "-0400" if dst_start <= utc_value < dst_end else "-0500"


def exact_commit_envelope(repository: Path, oid: str) -> dict[str, Any]:
    raw = run_git_bytes(repository, "cat-file", "commit", oid)
    require(b"\r" not in raw and b"\n\n" in raw, f"noncanonical commit object framing: {oid}")
    header_raw, message_raw = raw.split(b"\n\n", 1)
    lines = header_raw.split(b"\n")
    require(len(lines) == 4, f"successor commit has extra, missing, or signed headers: {oid}")
    tree_match = re.fullmatch(rb"tree ([0-9a-f]{40})", lines[0])
    parent_match = re.fullmatch(rb"parent ([0-9a-f]{40})", lines[1])
    identity = rb"acblabs <abaio@acblabs\.com>"
    author_match = re.fullmatch(rb"author " + identity + rb" ([0-9]+) ([+-][0-9]{4})", lines[2])
    committer_match = re.fullmatch(
        rb"committer " + identity + rb" ([0-9]+) ([+-][0-9]{4})", lines[3]
    )
    require(
        tree_match is not None and parent_match is not None,
        f"successor commit tree/parent header mismatch: {oid}",
    )
    require(
        author_match is not None and committer_match is not None,
        f"successor commit author/committer identity mismatch: {oid}",
    )
    assert tree_match is not None and parent_match is not None
    assert author_match is not None and committer_match is not None
    require(
        author_match.groups() == committer_match.groups(),
        f"successor commit author/committer dates differ: {oid}",
    )
    try:
        committed_at = dt.datetime.fromtimestamp(int(author_match.group(1)), tz=dt.timezone.utc)
        message = message_raw.decode("utf-8", "strict")
    except (OverflowError, OSError, UnicodeDecodeError, ValueError) as exc:
        raise ValidationError(f"successor commit date/message is invalid: {oid}") from exc
    require(
        message_raw.endswith(b"\n") and not message_raw.endswith(b"\n\n"),
        f"successor commit message must have exactly one terminal LF: {oid}",
    )
    timezone = author_match.group(2).decode("ascii")
    require(
        timezone == new_york_git_offset(committed_at),
        f"successor commit timezone does not match America/New_York civil time: {oid}",
    )
    return {
        "tree": tree_match.group(1).decode("ascii"),
        "parent": parent_match.group(1).decode("ascii"),
        "committed_at": committed_at,
        "timezone": timezone,
        "message": message[:-1],
        "message_raw": message_raw,
    }


def validate_exact_commit(
    repository: Path,
    oid: str,
    *,
    parent: str,
    tree: str | None,
    message: str | None,
    role: str,
) -> dt.datetime:
    require(re.fullmatch(r"[0-9a-f]{40}", oid) is not None, f"invalid {role} commit OID")
    require(run_git(repository, "cat-file", "-t", oid) == "commit", f"{role} is not a commit")
    envelope = exact_commit_envelope(repository, oid)
    require(
        envelope["parent"] == parent and exact_commit_parents(repository, oid) == [parent],
        f"{role} is not the exact sole-parent child of {parent}",
    )
    observed_tree = run_git(repository, "rev-parse", f"{oid}^{{tree}}")
    require(envelope["tree"] == observed_tree, f"{role} raw tree header mismatch")
    if tree is not None:
        require(observed_tree == tree, f"{role} tree mismatch")
    if message is not None:
        require(
            envelope["message_raw"] == message.encode("utf-8") + b"\n",
            f"{role} commit message mismatch",
        )
    return envelope["committed_at"]


def exact_delta_descriptors(repository: Path, parent: str, child: str) -> list[dict[str, Any]]:
    paths = run_git(
        repository,
        "diff-tree",
        "--no-commit-id",
        "--name-only",
        "-r",
        "--no-renames",
        parent,
        child,
        "--",
    ).splitlines()
    require(paths == sorted(paths), f"Git delta is not path-sorted: {parent}..{child}")
    require(
        len(paths) == len(set(path.casefold() for path in paths)),
        "Git delta contains duplicate/case-fold-colliding paths",
    )
    result: list[dict[str, Any]] = []
    for path in paths:
        safe_relative_path(path)
        row = run_git(repository, "ls-tree", child, "--", path)
        match = re.fullmatch(r"([0-7]{6}) blob ([0-9a-f]{40})\t(.+)", row)
        require(
            match is not None and match.group(3) == path,
            f"delta path is not one exact regular blob: {path}",
        )
        assert match is not None
        require(
            match.group(1) in {"100644", "100755"},
            f"forbidden delta mode at {path}: {match.group(1)}",
        )
        raw = run_git_bytes(repository, "cat-file", "blob", match.group(2))
        result.append(
            {
                "path": path,
                "mode": match.group(1),
                "git_blob_oid": match.group(2),
                "bytes": len(raw),
                "sha256": sha256(raw),
            }
        )
    return result


def git_delta_digest(repository: Path, parent: str, child: str) -> str:
    return domain_digest(
        "agent-assure:s1-successor-git-delta/v1", exact_delta_descriptors(repository, parent, child)
    )


def validate_tree_files_match_directory(
    repository: Path,
    commit: str,
    root: str,
    relative_paths: Iterable[str],
    directory: Path,
) -> None:
    for relative in sorted(relative_paths):
        safe_relative_path(relative)
        tree_path = root + "/" + relative
        row = run_git(repository, "ls-tree", commit, "--", tree_path)
        match = re.fullmatch(r"100644 blob ([0-9a-f]{40})\t(.+)", row)
        require(
            match is not None and match.group(2) == tree_path,
            f"installed governed file is not one ordinary 100644 blob: {tree_path}",
        )
        require(
            run_git_bytes(repository, "show", f"{commit}:{tree_path}")
            == read_bytes(directory / relative),
            f"installed bytes differ from {commit}:{tree_path}",
        )


def validate_standalone_object_store(repository: Path) -> None:
    """Prove the clone's live object bytes are ordinary, non-hardlinked local files."""

    object_root = repository / ".git" / "objects"
    assert_no_reparse_chain(object_root, "standalone Git object store")
    require(object_root.is_dir(), "standalone Git object store is missing")
    candidates = assert_no_reparse_tree(
        object_root,
        "standalone Git object store",
        maximum_entries=REPOSITORY_MAX_TREE_ENTRIES,
    )
    file_count = 0
    for candidate, is_directory in candidates:
        metadata = candidate.lstat()
        require(
            not candidate.is_symlink()
            and not bool(
                getattr(metadata, "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT
            ),
            f"standalone Git object store contains a reparse point: {candidate}",
        )
        if is_directory:
            continue
        require(
            candidate.is_file(),
            f"standalone Git object store contains a non-file entry: {candidate}",
        )
        require(metadata.st_nlink == 1, f"standalone Git object file is hard-linked: {candidate}")
        file_count += 1
    require(file_count > 0, "standalone Git object store contains no object files")


